insert into exercises (name, slug, description, instructions, main_muscle, secondary_muscles, equipment, difficulty, type, image_url, images, force, mechanic, common_mistakes, tips, recommended_sets, recommended_reps, recommended_rest_seconds, alternatives) values
('3/4 Sit-Up','3-4-sit-up','Ejercicio de tirón, compuesto.',ARRAY['Lie down on the floor and secure your feet. Your legs should be bent at the knees.','Place your hands behind or to the side of your head. You will begin with your back on the ground. This will be your starting position.','Flex your hips and spine to raise your torso toward your knees.','At the top of the contraction your torso should be perpendicular to the ground. Reverse the motion, going only ¾ of the way down.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/3_4_Sit-Up/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/3_4_Sit-Up/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/3_4_Sit-Up/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Air Bike','air-bike','Ejercicio de tirón, compuesto.',ARRAY['Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.','Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position.','Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing in the knee of the left leg. Bring your right elbow close to your left knee by crunching to the side, as you breathe out.','Go back to the initial position as you breathe in.','Crunch to the opposite side as you cycle your legs and bring closer your left elbow to your right knee and exhale.','Continue alternating in this manner until all of the recommended repetitions for each side have been completed.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Air_Bike/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Air_Bike/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Air_Bike/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Barbell Ab Rollout','barbell-ab-rollout','Ejercicio de tirón, compuesto.',ARRAY['For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position.','While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all times. Also your arms should be staying perpendicular to the floor throughout the movement. If you don''t, you will work out your shoulders and back more than the abs.','After a second contraction at the top, start to roll the barbell back forward to the starting position slowly as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY['espalda','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Ab_Rollout/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Ab_Rollout/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Ab_Rollout/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Barbell Rollout from Bench','barbell-rollout-from-bench','Ejercicio de tirón, compuesto.',ARRAY['Place a loaded barbell on the ground, near the end of a bench. Kneel with both legs on the bench, and take a medium to narrow grip on the barbell. This will be your starting position.','To begin, extend through the hips to slowly roll the bar forward. As you roll out, flex the shoulder to roll the bar above your head. Ensure that your arms remain extended throughout the movement.','When the bar has been moved as far forward as possible, return to the starting position.']::text[],'abdomen',ARRAY['gluteos','piernas','espalda','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Rollout_from_Bench/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Rollout_from_Bench/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Rollout_from_Bench/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Bent-Knee Hip Raise','bent-knee-hip-raise','Ejercicio de tirón, compuesto.',ARRAY['Lay flat on the floor with your arms next to your sides.','Now bend your knees at around a 75 degree angle and lift your feet off the floor by around 2 inches.','Using your lower abs, bring your knees in towards you as you maintain the 75 degree angle bend in your legs. Continue this movement until you raise your hips off of the floor by rolling your pelvis backward. Breathe out as you perform this portion of the movement. Tip: At the end of the movement your knees will be over your chest.','Squeeze your abs at the top of the movement for a second and then return to the starting position slowly as you breathe in. Tip: Maintain a controlled motion at all times.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent-Knee_Hip_Raise/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent-Knee_Hip_Raise/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent-Knee_Hip_Raise/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Bottoms Up','bottoms-up','Ejercicio de tirón, compuesto.',ARRAY['Begin by lying on your back on the ground. Your legs should be straight and your arms at your side. This will be your starting position.','To perform the movement, tuck the knees toward your chest by flexing the hips and knees. Following this, extend your legs directly above you so that they are perpendicular to the ground. Rotate and elevate your pelvis to raise your glutes from the floor.','After a brief pause, return to the starting position.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bottoms_Up/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bottoms_Up/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bottoms_Up/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Butt-Ups','butt-ups','Ejercicio de tirón, compuesto.',ARRAY['Begin a pushup position but with your elbows on the ground and resting on your forearms. Your arms should be bent at a 90 degree angle.','Arch your back slightly out rather than keeping your back completely straight.','Raise your glutes toward the ceiling, squeezing your abs tightly to close the distance between your ribcage and hips. The end result will be that you''ll end up in a high bridge position. Exhale as you perform this portion of the movement.','Lower back down slowly to your starting position as you breathe in. Tip: Don''t let your back sag downwards.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Butt-Ups/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Butt-Ups/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Butt-Ups/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cable Judo Flip','cable-judo-flip','Ejercicio de tirón, compuesto.',ARRAY['Connect a rope attachment to a tower, and move the cable to the lowest pulley position. Stand with your side to the cable with a wide stance, and grab the rope with both hands.','Twist your body away from the pulley as you bring the rope over your shoulder like you''re performing a judo flip.','Shift your weight between your feet as you twist and crunch forward, pulling the cable downward.','Return to the starting position and repeat until failure.','Then, reposition and repeat the same series of movements on the opposite side.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Judo_Flip/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Judo_Flip/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Judo_Flip/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cable Russian Twists','cable-russian-twists','Ejercicio de tirón, compuesto.',ARRAY['Connect a standard handle attachment, and position the cable to a middle pulley position.','Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.','Grab the handle with both hands and fully extend your arms above your chest. You hands should be directly in-line with the pulley. If not, adjust the pulley up or down until they are.','Keep your hips elevated and abs engaged. Rotate your torso away from the pulley for a full-quarter rotation. Your body should be flat from head to knees.','Pause for a moment and in a slow and controlled manner reset to the starting position. You should still have side tension on the cable in the resting position.','Repeat the same movement to failure.','Then, reposition and repeat the same series of movements on the opposite side.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Russian_Twists/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Russian_Twists/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Russian_Twists/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cocoons','cocoons','Ejercicio de tirón, compuesto.',ARRAY['Begin by lying on your back on the ground. Your legs should be straight and your arms extended behind your head. This will be your starting position.','To perform the movement, tuck the knees toward your chest, rotating your pelvis to lift your glutes from the floor. As you do so, flex the spine, bringing your arms back over your head to perform a simultaneous crunch motion.','After a brief pause, return to the starting position.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cocoons/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cocoons/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cocoons/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cross-Body Crunch','cross-body-crunch','Ejercicio de tirón, compuesto.',ARRAY['Lie flat on your back and bend your knees about 60 degrees.','Keep your feet flat on the floor and place your hands loosely behind your head. This will be your starting position.','Now curl up and bring your right elbow and shoulder across your body while bring your left knee in toward your left shoulder at the same time. Reach with your elbow and try to touch your knee. Exhale as you perform this movement. Tip: Try to bring your shoulder up towards your knee rather than just your elbow and remember that the key is to contract the abs as you perform the movement; not just to move the elbow.','Now go back down to the starting position as you inhale and repeat with the left elbow and the right knee.','Continue alternating in this manner until all prescribed repetitions are done.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cross-Body_Crunch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cross-Body_Crunch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cross-Body_Crunch/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Dead Bug','dead-bug','Ejercicio de tirón, compuesto.',ARRAY['Begin lying on your back with your hands extended above you toward the ceiling.','Bring your feet, knees, and hips up to 90 degrees.','Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.','Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.','Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.','Stay tight and return the working leg to the starting position.','Repeat on the opposite side, alternating until the set is complete.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dead_Bug/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dead_Bug/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dead_Bug/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Decline Oblique Crunch','decline-oblique-crunch','Ejercicio de tirón, compuesto.',ARRAY['Secure your legs at the end of the decline bench and slowly lay down on the bench.','Raise your upper body off the bench until your torso is about 35-45 degrees if measured from the floor.','Put one hand beside your head and the other on your thigh. This will be your starting position.','Raise your upper body slowly from the starting position while turning your torso to the left. Continue crunching up as you exhale until your right elbow touches your left knee. Hold this contracted position for a second. Tip: Focus on keeping your abs tight and keeping the movement slow and controlled.','Lower your body back down slowly to the starting position as you inhale.','After completing one set on the right for the recommended amount of repetitions, switch to your left side. Tip: Focus on really twisting your torso and feeling the contraction when you are in the up position.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Oblique_Crunch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Oblique_Crunch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Oblique_Crunch/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Decline Reverse Crunch','decline-reverse-crunch','Ejercicio de tirón, compuesto.',ARRAY['Lie on your back on a decline bench and hold on to the top of the bench with both hands. Don''t let your body slip down from this position.','Hold your legs parallel to the floor using your abs to hold them there while keeping your knees and feet together. Tip: Your legs should be fully extended with a slight bend on the knee. This will be your starting position.','While exhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the bench. At the end of this movement your knees will be touching your chest.','Hold the contraction for a second and move your legs back to the starting position while inhaling.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Reverse_Crunch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Reverse_Crunch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Reverse_Crunch/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Elbow to Knee','elbow-to-knee','Ejercicio de tirón, compuesto.',ARRAY['Lie on the floor, crossing your right leg across your bent left knee. Clasp your hands behind your head, beginning with your shoulder blades on the ground. This will be your starting position.','Perform the motion by flexing the spine and rotating your torso to bring the left elbow to the right knee.','Return to the starting position and repeat the movement for the desired number of repetitions before switching sides.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Elbow_to_Knee/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Elbow_to_Knee/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Elbow_to_Knee/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Flat Bench Leg Pull-In','flat-bench-leg-pull-in','Ejercicio de tirón, compuesto.',ARRAY['Lie on an exercise mat or a flat bench with your legs off the end.','Place your hands either under your glutes with your palms down or by the sides holding on to the bench (or with palms down by the side on an exercise mat). Also extend your legs straight out. This will be your starting position.','Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue this movement until your knees are near your chest. Hold the contracted position for a second.','As you breathe in, slowly return to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Flat_Bench_Leg_Pull-In/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Flat_Bench_Leg_Pull-In/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Flat_Bench_Leg_Pull-In/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Gorilla Chin/Crunch','gorilla-chin-crunch','Ejercicio de tirón, compuesto.',ARRAY['Hang from a chin-up bar using an underhand grip (palms facing you) that is slightly wider than shoulder width.','Now bend your knees at a 90 degree angle so that the calves are parallel to the floor while the thighs remain perpendicular to it. This will be your starting position.','As you exhale, pull yourself up while crunching your knees up at the same time until your knees are at chest level. You will stop going up as soon as your nose is at the same level as the bar. Tip: When you get to this point you should also be finishing the crunch at the same time.','Slowly start to inhale as you return to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY['biceps','espalda']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Gorilla_Chin_Crunch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Gorilla_Chin_Crunch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Gorilla_Chin_Crunch/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Jackknife Sit-Up','jackknife-sit-up','Ejercicio de tirón, compuesto.',ARRAY['Lie flat on the floor (or exercise mat) on your back with your arms extended straight back behind your head and your legs extended also. This will be your starting position.','As you exhale, bend at the waist while simultaneously raising your legs and arms to meet in a jackknife position. Tip: The legs should be extended and lifted at approximately a 35-45 degree angle from the floor and the arms should be extended and parallel to your legs. The upper torso should be off the floor.','While inhaling, lower your arms and legs back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Jackknife_Sit-Up/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Jackknife_Sit-Up/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Jackknife_Sit-Up/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Kettlebell Pass Between The Legs','kettlebell-pass-between-the-legs','Ejercicio de tirón, compuesto.',ARRAY['Place one kettlebell between your legs and take a comfortable stance. Bend over by pushing your butt out and keeping your back flat.','Pick up a kettlebell and pass it to your other hand between your legs, in the fashion of a "W". Go back and forth for several repetitions.']::text[],'abdomen',ARRAY['gluteos','piernas','hombros']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Pass_Between_The_Legs/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Pass_Between_The_Legs/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Pass_Between_The_Legs/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Kettlebell Windmill','kettlebell-windmill','Ejercicio de tirón, compuesto.',ARRAY['Place a kettlebell in front of your lead foot and clean and press it overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward. Press it overhead by extending the elbow.','Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell. Bending at the hip to one side, sticking your butt out, slowly lean until you can touch the floor with your free hand. Keep your eyes on the kettlebell that you hold over your head at all times.','Pause for a second after reaching the ground and reverse the motion back to the starting position.']::text[],'abdomen',ARRAY['gluteos','piernas','hombros','triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Windmill/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Windmill/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Windmill/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Landmine 180''s','landmine-180s','Ejercicio de tirón, compuesto.',ARRAY['Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.','Raise the bar from the floor, taking it to shoulder height with both hands with your arms extended in front of you. Adopt a wide stance. This will be your starting position.','Perform the movement by rotating the trunk and hips as you swing the weight all the way down to one side. Keep your arms extended throughout the exercise.','Reverse the motion to swing the weight all the way to the opposite side.','Continue alternating the movement until the set is complete.']::text[],'abdomen',ARRAY['gluteos','espalda','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Landmine_180s/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Landmine_180s/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Landmine_180s/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Leg Pull-In','leg-pull-in','Ejercicio de tirón, compuesto.',ARRAY['Lie on an exercise mat with your legs extended and your hands either palms facing down next to you or under your glutes. Tip: My preference is with the hands next to me. This will be your starting position.','Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue the motion until your knees are around chest level. Contract your abs as you execute this movement and hold for a second at the top. Tip: As you perform the motion, the lower legs (calves) should always remain parallel to the floor.','Return to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leg_Pull-In/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leg_Pull-In/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leg_Pull-In/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Pallof Press With Rotation','pallof-press-with-rotation','Ejercicio de tirón, compuesto.',ARRAY['Connect a standard handle to a tower, and position the cable to shoulder height.','With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Align outstretched arm with cable.','With your feet positioned hip-width apart, pull the cable into your chest and grab the handle with your other hand. Both hands should be on the handle at this time.','Facing forward, press the cable away from your chest. You core should be tight and engaged.','Keeping your hips straight, twist your torso away from the pulley until you get a full quarter rotation.','Maintain your rigid stance and straight arms. Return to the neutral position in a slow and controlled manner. Your arms should be extended in front of you.','With the side tension still engaging your core, bring your hands to your chest and immediately press outward to a fully extended position. This constitutes one rep.','Repeat to failure.','Then, reposition and repeat the same series of movements on the opposite side.']::text[],'abdomen',ARRAY['pecho','hombros','triceps']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Pallof_Press_With_Rotation/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Pallof_Press_With_Rotation/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Pallof_Press_With_Rotation/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Russian Twist','russian-twist','Ejercicio de tirón, compuesto.',ARRAY['Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.','Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position.','Twist your torso to the right side until your arms are parallel with the floor while breathing out.','Hold the contraction for a second and move back to the starting position while breathing out. Now move to the opposite side performing the same techniques you applied to the right side.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY['espalda']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Russian_Twist/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Russian_Twist/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Russian_Twist/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Seated Flat Bench Leg Pull-In','seated-flat-bench-leg-pull-in','Ejercicio de tirón, compuesto.',ARRAY['Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.','Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement.','After a second pause, go back to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Seated_Flat_Bench_Leg_Pull-In/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Seated_Flat_Bench_Leg_Pull-In/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Seated_Flat_Bench_Leg_Pull-In/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Side Jackknife','side-jackknife','Ejercicio de tirón, compuesto.',ARRAY[]::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Side_Jackknife/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Side_Jackknife/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Side_Jackknife/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Spell Caster','spell-caster','Ejercicio de tirón, compuesto.',ARRAY['Hold a dumbbell in each hand with a pronated grip. Your feet should be wide with your hips and knees extended. This will be your starting position.','Begin the movement by pulling both of the dumbbells to one side next to your hip, rotating your torso.','Keeping your arms straight and the dumbbells parallel to the ground, rotate your torso to swing the weights to your opposite side.','Continue alternating, rotating from one side to the other until the set is complete.']::text[],'abdomen',ARRAY['gluteos','hombros']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Spell_Caster/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Spell_Caster/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Spell_Caster/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Spider Crawl','spider-crawl','Ejercicio de tirón, compuesto.',ARRAY['Begin in a prone position on the floor. Support your weight on your hands and toes, with your feet together and your body straight. Your arms should be bent to 90 degrees. This will be your starting position.','Initiate the movement by raising one foot off of the ground. Externally rotate the leg and bring the knee toward your elbow, as far forward as possible.','Return this leg to the starting position and repeat on the opposite side.']::text[],'abdomen',ARRAY['pecho','hombros','triceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Spider_Crawl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Spider_Crawl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Spider_Crawl/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Standing Cable Lift','standing-cable-lift','Ejercicio de tirón, compuesto.',ARRAY['Connect a standard handle on a tower, and move the cable to the lowest pulley position.','With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.','With your feet positioned shoulder width apart, squat down and grab the handle with both hands. Your arms should still be fully extended.','In one motion, pull the handle up and across your body until your arms are in a fully-extended position above your head.','Keep your back straight and your arms close to your body as you pivot your back foot and straighten your legs to get a full range of motion.','Retract your arms and then your body. Return to the neutral position in a slow and controlled manner.','Repeat to failure.','Then, reposition and repeat the same series of movements on the opposite side.']::text[],'abdomen',ARRAY['hombros']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Standing_Cable_Lift/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Standing_Cable_Lift/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Standing_Cable_Lift/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Standing Cable Wood Chop','standing-cable-wood-chop','Ejercicio de tirón, compuesto.',ARRAY['Connect a standard handle to a tower, and move the cable to the highest pulley position.','With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.','With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extended.','In one motion, pull the handle down and across your body to your front knee while rotating your torso.','Keep your back and arms straight and core tight while you pivot your back foot and bend your knees to get a full range of motion.','Maintain your stance and straight arms. Return to the neutral position in a slow and controlled manner.','Repeat to failure.','Then, reposition and repeat the same series of movements on the opposite side.']::text[],'abdomen',ARRAY['hombros']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Standing_Cable_Wood_Chop/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Standing_Cable_Wood_Chop/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Standing_Cable_Wood_Chop/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Wind Sprints','wind-sprints','Ejercicio de tirón, compuesto.',ARRAY['Hang from a pull-up bar using a pronated grip. Your arms and legs should be extended. This will be your starting position.','Begin by quickly raising one knee as high as you can. Do not swing your body or your legs. 3','Immediately reverse the motion, returning that leg to the starting position. Simultaneously raise the opposite knee as high as possible.','Continue alternating between legs until the set is complete.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Wind_Sprints/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Wind_Sprints/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Wind_Sprints/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Ab Crunch Machine','ab-crunch-machine','Ejercicio de tirón, aislamiento.',ARRAY['Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.','At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.','After a second pause, slowly return to the starting position as you breathe in.','Repeat the movement for the prescribed amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ab_Crunch_Machine/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ab_Crunch_Machine/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ab_Crunch_Machine/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Advanced Kettlebell Windmill','advanced-kettlebell-windmill','Ejercicio de empuje, aislamiento.',ARRAY['Clean and press a kettlebell overhead with one arm.','Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Keep the non-working arm behind your back and turn your feet out at a forty-five degree angle from the arm with the kettlebell.','Lower yourself as far as possible.','Pause for a second and reverse the motion back to the starting position.']::text[],'abdomen',ARRAY['gluteos','piernas','hombros']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Advanced_Kettlebell_Windmill/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Advanced_Kettlebell_Windmill/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Advanced_Kettlebell_Windmill/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Alternate Heel Touchers','alternate-heel-touchers','Ejercicio de tirón, aislamiento.',ARRAY['Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position.','Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement.','Now go back slowly to the starting position as you inhale.','Now crunch over your torso forward and up around 3-4 inches to the left side and touch your left heel as you hold the contraction for a second. Exhale while performing this movement and then go back to the starting position as you inhale. Now that both heels have been touched, that is considered 1 repetition.','Continue alternating sides in this manner until all prescribed repetitions are done.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Heel_Touchers/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Heel_Touchers/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Heel_Touchers/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Barbell Ab Rollout - On Knees','barbell-ab-rollout-on-knees','Ejercicio de tirón, compuesto.',ARRAY['Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.','Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.','Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.','After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.']::text[],'abdomen',ARRAY['espalda','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Ab_Rollout_-_On_Knees/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Ab_Rollout_-_On_Knees/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Ab_Rollout_-_On_Knees/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Barbell Side Bend','barbell-side-bend','Ejercicio de tirón, aislamiento.',ARRAY['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be shoulder width apart. This will be your starting position.','While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.','Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY['espalda']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Side_Bend/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Side_Bend/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Side_Bend/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Bent Press','bent-press','Ejercicio de tirón, compuesto.',ARRAY['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. This will be your starting position.','Begin my leaning to the side opposite the kettlebell, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebell. As you do so, press the weight vertically be extending through the elbow, keeping your arm perpendicular to the ground.','Return to an upright position, with the kettlebell above your head. Return the kettlebell to the shoulder and repeat for the desired number of repetitions.']::text[],'abdomen',ARRAY['gluteos','piernas','espalda','hombros','triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Press/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Bosu Ball Cable Crunch With Side Bends','bosu-ball-cable-crunch-with-side-bends','Ejercicio de tirón, aislamiento.',ARRAY['Connect a standard handle to each arm of a cable machine, and position them in the most downward position.','Grab a Bosu Ball and position it in front and center of the cable machine.','Lie down on the Bosu Ball with the small of your back arched around the ball. Your rear end should be close to the floor without touching it.','With both hands, reach back and grab the handle of each cable.','With your feet positioned in a wide stance, extend your arms straight out in front of you and in between your knees. Your hands should be at knee level.','Keep your arms straight and in-line with the upward angle of the cable. Elevate your torso in a crunching motion without dropping or bending your arms.','Maintain the rigid position with your arms. Slowly descend back to the starting position with your back arched around the Bosu Ball and your abdominals elongated.','Repeat the same series of movements to failure.','Once you reach failure, keep your abs tight and raise your torso into plank position so your back is elevated off the Bosu Ball.','Lower your arms down to your side; keep them straight. Start doing alternating side bends; reach for your heels! This finishing movement will focus on your obliques.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bosu_Ball_Cable_Crunch_With_Side_Bends/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bosu_Ball_Cable_Crunch_With_Side_Bends/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bosu_Ball_Cable_Crunch_With_Side_Bends/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Bottoms-Up Clean From The Hang Position','bottoms-up-clean-from-the-hang-position','Ejercicio de tirón, compuesto.',ARRAY['Initiate the exercise by standing upright with a kettlebell in one hand.','Swing the kettlebell back forcefully and then reverse the motion forcefully. Crush the kettlebell handle as hard as possible and raise the kettlebell to your shoulder.']::text[],'biceps',ARRAY['hombros']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bottoms-Up_Clean_From_The_Hang_Position/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bottoms-Up_Clean_From_The_Hang_Position/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bottoms-Up_Clean_From_The_Hang_Position/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Drag Curl','drag-curl','Ejercicio de tirón, compuesto.',ARRAY['Grab a barbell with a supinated grip (palms facing forward) and get your elbows close to your torso and back. This will be your starting position.','As you exhale, curl the bar up while keeping the elbows to the back as you "Drag" the bar up by keeping it in contact with your torso. Tip: As you can see, you will not be keeping the elbows pinned to your sides, but instead you will be bringing them back. Also, do not lift your shoulders.','Slowly go back to the starting position as you keep the bar in contact with the torso at all times.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Drag_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Drag_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Drag_Curl/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('High Cable Curls','high-cable-curls','Ejercicio de tirón, compuesto.',ARRAY['Stand between a couple of high pulleys and grab a handle in each arm. Position your upper arms in a way that they are parallel to the floor with the palms of your hands facing you. This will be your starting position.','Curl the handles towards you until they are next to your ears. Make sure that as you do so you flex your biceps and exhale. The upper arms should remain stationary and only the forearms should move. Hold for a second in the contracted position as you squeeze the biceps.','Slowly bring back the arms to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/High_Cable_Curls/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/High_Cable_Curls/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/High_Cable_Curls/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Alternate Hammer Curl','alternate-hammer-curl','Ejercicio de tirón, aislamiento.',ARRAY['Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.','The palms of the hands should be facing your torso. This will be your starting position.','While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.','Slowly begin to bring the dumbbells back to starting position as your breathe in.','Repeat the movement with the left hand. This equals one repetition.','Continue alternating in this manner for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Hammer_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Hammer_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Hammer_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Alternate Incline Dumbbell Curl','alternate-incline-dumbbell-curl','Ejercicio de tirón, aislamiento.',ARRAY['Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position.','While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. As you do so, rotate the hand so that the palm is facing up. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.','Slowly begin to bring the dumbbell back to starting position as your breathe in.','Repeat the movement with the left hand. This equals one repetition.','Continue alternating in this manner for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Incline_Dumbbell_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Incline_Dumbbell_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Incline_Dumbbell_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Barbell Curl','barbell-curl','Ejercicio de tirón, aislamiento.',ARRAY['Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.','While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.','Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.','Slowly begin to bring the bar back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Barbell Curls Lying Against An Incline','barbell-curls-lying-against-an-incline','Ejercicio de tirón, aislamiento.',ARRAY['Lie against an incline bench, with your arms holding a barbell and hanging down in a horizontal line. This will be your starting position.','While keeping the upper arms stationary, curl the weight up as high as you can while squeezing the biceps. Breathe out as you perform this portion of the movement. Tip: Only the forearms should move. Do not swing the arms.','After a second contraction, slowly go back to the starting position as you inhale. Tip: Make sure that you go all of the way down.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Curls_Lying_Against_An_Incline/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Curls_Lying_Against_An_Incline/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Curls_Lying_Against_An_Incline/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cable Hammer Curls - Rope Attachment','cable-hammer-curls-rope-attachment','Ejercicio de tirón, aislamiento.',ARRAY['Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.','Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary.','Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position.','Using your biceps, pull your arms up as you exhale until your biceps touch your forearms. Tip: Remember to keep the elbows in and your upper arms stationary.','After a 1 second contraction where you squeeze your biceps, slowly start to bring the weight back to the original position.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Hammer_Curls_-_Rope_Attachment/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Hammer_Curls_-_Rope_Attachment/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Hammer_Curls_-_Rope_Attachment/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cable Preacher Curl','cable-preacher-curl','Ejercicio de tirón, aislamiento.',ARRAY['Place a preacher bench about 2 feet in front of a pulley machine.','Attach a straight bar to the low pulley.','Sit at the preacher bench with your elbow and upper arms firmly on top of the bench pad and have someone hand you the bar from the low pulley.','Grab the bar and fully extend your arms on top of the preacher bench pad. This will be your starting position.','Now start pilling the weight up towards your shoulders and squeeze the biceps hard at the top of the movement. Exhale as you perform this motion. Also, hold for a second at the top.','Now slowly lower the weight to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Preacher_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Preacher_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Preacher_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cable Wrist Curl','cable-wrist-curl','Ejercicio de tirón, aislamiento.',ARRAY['Start out by placing a flat bench in front of a low pulley cable that has a straight bar attachment.','Use your arms to grab the cable bar with a narrow to shoulder width supinated grip (palms up) and bring them up so that your forearms are resting against the top of your thighs. Your wrists should be hanging just beyond your knees.','Start out by curling your wrist upwards and exhaling. Keep the contraction for a second.','Slowly lower your wrists back down to the starting position while inhaling.','Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Wrist_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Wrist_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Wrist_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Close-Grip EZ-Bar Curl with Band','close-grip-ez-bar-curl-with-band','Ejercicio de tirón, aislamiento.',ARRAY['Attach a band to each end of the bar. Take the bar, placing a foot on the middle of the band. Stand upright with a narrow, supinated grip on the EZ bar. The elbows should be close to the torso. This will be your starting position.','While keeping the upper arms in place, flex the elbows to execute the curl. Exhale as the weight is lifted.','Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.','Slowly begin to bring the bar back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_EZ-Bar_Curl_with_Band/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_EZ-Bar_Curl_with_Band/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_EZ-Bar_Curl_with_Band/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Close-Grip EZ Bar Curl','close-grip-ez-bar-curl','Ejercicio de tirón, aislamiento.',ARRAY['Stand up with your torso upright while holding an E-Z Curl Bar at the closer inner handle. The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar. The elbows should be close to the torso. This will be your starting position.','While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.','Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.','Slowly begin to bring the bar back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_EZ_Bar_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_EZ_Bar_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_EZ_Bar_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Close-Grip Standing Barbell Curl','close-grip-standing-barbell-curl','Ejercicio de tirón, aislamiento.',ARRAY['Hold a barbell with both hands, palms up and a few inches apart.','Stand with your torso straight and your head up. Your feet should be about shoulder width and your elbows close to your torso. This will be your starting position. Tip: You will keep your upper arms and elbows stationary throughout the movement.','Curl the bar up in a semicircular motion until the forearms touch your biceps. Exhale as you perform this portion of the movement and contract your biceps hard for a second at the top. Tip: Avoid bending the back or using swinging motions as you lift the weight. Only the forearms should move.','Slowly go back down to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_Standing_Barbell_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_Standing_Barbell_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_Standing_Barbell_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Concentration Curls','concentration-curls','Ejercicio de tirón, aislamiento.',ARRAY['Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.','Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position.','While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: At the top of the movement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.','Slowly begin to bring the dumbbells back to starting position as your breathe in. Caution: Avoid swinging motions at any time.','Repeat for the recommended amount of repetitions. Then repeat the movement with the left arm.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Concentration_Curls/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Concentration_Curls/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Concentration_Curls/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cross Body Hammer Curl','cross-body-hammer-curl','Ejercicio de tirón, aislamiento.',ARRAY['Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in.','While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second.','Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm.','Continue alternating in this fashion until the recommended amount of repetitions is performed for each arm.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cross_Body_Hammer_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cross_Body_Hammer_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cross_Body_Hammer_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Dumbbell Alternate Bicep Curl','dumbbell-alternate-bicep-curl','Ejercicio de tirón, aislamiento.',ARRAY['Stand (torso upright) with a dumbbell in each hand held at arms length. The elbows should be close to the torso and the palms of your hand should be facing your thighs.','While holding the upper arm stationary, curl the right weight as you rotate the palm of the hands until they are facing forward. At this point continue contracting the biceps as you breathe out until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.','Slowly begin to bring the dumbbell back to the starting position as your breathe in. Tip: Remember to twist the palms back to the starting position (facing your thighs) as you come down.','Repeat the movement with the left hand. This equals one repetition.','Continue alternating in this manner for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Alternate_Bicep_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Alternate_Bicep_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Alternate_Bicep_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Dumbbell Bicep Curl','dumbbell-bicep-curl','Ejercicio de tirón, aislamiento.',ARRAY['Stand up straight with a dumbbell in each hand at arm''s length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.','Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.','Then, inhale and slowly begin to lower the dumbbells back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Bicep_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Bicep_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Bicep_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Dumbbell Lying Pronation','dumbbell-lying-pronation','Ejercicio de tirón, aislamiento.',ARRAY['Lie on a flat bench face down with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.','Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.','Now raise the upper arm so that the forearm is perpendicular to the floor and the upper arm is perpendicular to your torso. Tip: The upper arm should be parallel to the floor and also creating a 90-degree angle with your torso. This will be your starting position.','As you breathe out, externally rotate your forearm so that the dumbbell is lifted forward as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is parallel to the floor. At this point you will hold the contraction for a second.','As you breathe in, slowly go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lying_Pronation/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lying_Pronation/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lying_Pronation/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Dumbbell Lying Supination','dumbbell-lying-supination','Ejercicio de tirón, aislamiento.',ARRAY['Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.','Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.','Now raise the upper arm so that the forearm is parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.','As you breathe out, externally rotate your forearm so that the dumbbell is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to the floor and the torso pointing towards the ceiling. At this point you will hold the contraction for a second.','As you breathe in, slowly go back to the starting position.','Repeat for the recommended amount of repetitions and then switch to the other arm.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lying_Supination/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lying_Supination/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lying_Supination/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Dumbbell Prone Incline Curl','dumbbell-prone-incline-curl','Ejercicio de tirón, aislamiento.',ARRAY['Grab a dumbbell on each hand and lie face down on an incline bench with your shoulders near top of the incline. Your knees can rest on the seat or your legs can be straddled to the sides (my preferred way).','Let your arms extend and hang naturally in front of you so that they are perpendicular to the floor.','Now keep your elbows in by your side and face the palms forward. This will be your starting position.','Raise the dumbbells by contracting the biceps until your arms are fully flexed. Exhale as you perform this portion of the movement and ensure that only the forearms move. The upper arms should remain stationary at all times.','Lower the dumbbells until your arms are fully extended.','Repeat for the recommended amount of times.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Prone_Incline_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Prone_Incline_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Prone_Incline_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('EZ-Bar Curl','ez-bar-curl','Ejercicio de tirón, aislamiento.',ARRAY['Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of your hands should be facing forward and slightly tilted inward due to the shape of the bar. Keep your elbows close to your torso. This will be your starting position.','Now, while keeping your upper arms stationary, exhale and curl the weights forward while contracting the biceps. Focus on only moving your forearms.','Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder level. Hold the top contracted position for a moment and squeeze the biceps.','Then inhale and slowly lower the bar back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/EZ-Bar_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/EZ-Bar_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/EZ-Bar_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Finger Curls','finger-curls','Ejercicio de tirón, aislamiento.',ARRAY['Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.','Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. This will be your starting position.','Lower the bar as far as possible by extending the fingers. Allowing the bar to roll down the hands, catch the bar with the final joint in the fingers.','Now curl bar up as high as possible by closing your hands while exhaling. Hold the contraction at the top.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Finger_Curls/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Finger_Curls/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Finger_Curls/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Flexor Incline Dumbbell Curls','flexor-incline-dumbbell-curls','Ejercicio de tirón, aislamiento.',ARRAY['Hold the dumbbell towards the side farther from you so that you have more weight on the side closest to you. (This can be done for a good effect on all bicep dumbbell exercises). Now do a normal incline dumbbell curl, but keep your wrists as far back as possible so as to neutralize any stress that is placed on them.','Sit on an incline bench that is angled at 45-degrees while holding a dumbbell on each hand.','Let your arms hang down on your sides, with the elbows in, and turn the palms of your hands forward with the thumbs pointing away from the body. Tip: You will keep this hand position throughout the movement as there should not be any twisting of the hands as they come up. This will be your starting position.','Curl up the two dumbbells at the same time until your biceps are fully contracted and exhale. Tip: Do not swing the arms or use momentum. Keep a controlled motion at all times. Hold the contracted position for a second at the top.','As you inhale, slowly go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Flexor_Incline_Dumbbell_Curls/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Flexor_Incline_Dumbbell_Curls/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Flexor_Incline_Dumbbell_Curls/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Hammer Curls','hammer-curls','Ejercicio de tirón, aislamiento.',ARRAY['Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.','The palms of the hands should be facing your torso. This will be your starting position.','Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.','After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hammer_Curls/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hammer_Curls/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hammer_Curls/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Incline Dumbbell Curl','incline-dumbbell-curl','Ejercicio de tirón, aislamiento.',ARRAY['Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.','While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.','Slowly begin to bring the dumbbells back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Dumbbell_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Dumbbell_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Dumbbell_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Incline Hammer Curls','incline-hammer-curls','Ejercicio de tirón, aislamiento.',ARRAY['Seat yourself on an incline bench with a dumbbell in each hand. You should pressed firmly against he back with your feet together. Allow the dumbbells to hang straight down at your side, holding them with a neutral grip. This will be your starting position.','Initiate the movement by flexing at the elbow, attempting to keep the upper arm stationary.','Continue to the top of the movement and pause, then slowly return to the start position.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Hammer_Curls/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Hammer_Curls/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Hammer_Curls/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Incline Inner Biceps Curl','incline-inner-biceps-curl','Ejercicio, aislamiento.',ARRAY['Hold a dumbbell in each hand and lie back on an incline bench.','The dumbbells should be at arm''s length hanging at your sides and your palms should be facing out. This will be your starting position.','Now as you exhale curl the weight outward and up while keeping your forearms in line with your side deltoids. Continue the curl until the dumbbells are at shoulder height and to the sides of your deltoids. Tip: The end of the movement should look similar to a double biceps pose.','After a second contraction at the top of the movement, start to inhale and slowly lower the weights back to the starting position using the same path used to bring them up.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Inner_Biceps_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Inner_Biceps_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Inner_Biceps_Curl/1.jpg']::text[],null,'Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Lying Cable Curl','lying-cable-curl','Ejercicio de tirón, aislamiento.',ARRAY['Grab a straight bar or E-Z bar attachment that is attached to the low pulley with both hands, using an underhand (palms facing up) shoulder-width grip.','Lie flat on your back on top of an exercise mat in front of the weight stack with your feet flat against the frame of the pulley machine and your legs straight.','With your arms extended and your elbows close to your body slightly bend your arms. This will be your starting position.','While keeping your upper arms stationary and the elbows close to your body, curl the bar up slowly toward your chest as you breathe out and you squeeze the biceps.','After a second squeeze at the top of the movement, slowly return to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Cable_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Cable_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Cable_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Lying Close-Grip Bar Curl On High Pulley','lying-close-grip-bar-curl-on-high-pulley','Ejercicio de tirón, aislamiento.',ARRAY['Place a flat bench in front of a high pulley or lat pulldown machine.','Hold the straight bar attachment using an underhand grip (palms up) that is about shoulder width.','Lie on your back with your head over the end of the bench.','Now extend your arms straight above your shoulders. Your torso and your arms should make a 90-degree angle and the elbows should be in. This will be your starting position.','As you breathe out, curl the bar down in a semicircular motion until it touches your chin. Squeeze the biceps for a second at the top contracted position. Tip: As you execute this motion only the forearms should move. At no time should the upper arms be moving at all. They are to remain perpendicular throughout the movement.','Return to starting position slowly.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Close-Grip_Bar_Curl_On_High_Pulley/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Close-Grip_Bar_Curl_On_High_Pulley/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Close-Grip_Bar_Curl_On_High_Pulley/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Lying High Bench Barbell Curl','lying-high-bench-barbell-curl','Ejercicio de tirón, aislamiento.',ARRAY['Lie face forward on a tall flat bench while holding a barbell with a supinated grip (palms facing up). Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles. Your upper body should be positioned in a way that the upper chest is over the end of the bench and the barbell is hanging in front of you with the arms extended and perpendicular to the floor. This will be your starting position.','While keeping the elbows in and the upper arms stationary, curl the weight up in a semi-circular motion as you contract the biceps and exhale. Hold at the top of the movement for a second.','As you inhale, slowly go back to the starting position. Tip: Maintain full control of the weight at all times and avoid any swinging. Remember, only the forearms should move throughout the movement.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_High_Bench_Barbell_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_High_Bench_Barbell_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_High_Bench_Barbell_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Lying Supine Dumbbell Curl','lying-supine-dumbbell-curl','Ejercicio de tirón, aislamiento.',ARRAY['Lie down on a flat bench face up while holding a dumbbell in each arm on top of your thighs.','Bring the dumbbells to the sides with the arms extended and the palms of the hands facing your thighs (neutral grip).','While keeping the arms close to your torso and elbows in, slowly lower your arms (as you keep them extended with a slight bend at the elbows) as far down towards the floor as you can go. Once you cannot go down any further, lock your upper arms in that position and that will be your starting position.','As you breathe out, slowly begin to curl the weights up as you simultaneously rotate your wrists so that the palms of the hands face up. Continue curling the weight until your biceps are fully contracted and squeeze hard at the top position for a second. Tip: Only the forearms should move. Upper arms should remain stationary and elbows should stay in throughout the movement.','Return back to the starting position very slowly.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Supine_Dumbbell_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Supine_Dumbbell_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Supine_Dumbbell_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Machine Bicep Curl','machine-bicep-curl','Ejercicio de tirón, aislamiento.',ARRAY['Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.','Perform the movement by flexing the elbow, pulling your lower arm towards your upper arm.','Pause at the top of the movement, and then slowly return the weight to the starting position.','Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Machine_Bicep_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Machine_Bicep_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Machine_Bicep_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Machine Preacher Curls','machine-preacher-curls','Ejercicio de tirón, aislamiento.',ARRAY['Sit down on the Preacher Curl Machine and select the weight.','Place the back of your upper arms (your triceps) on the preacher pad provided and grab the handles using an underhand grip (palms facing up). Tip: Make sure that when you place the arms on the pad you keep the elbows in. This will be your starting position.','Now lift the handles as you exhale and you contract the biceps. At the top of the position make sure that you hold the contraction for a second. Tip: Only the forearms should move. The upper arms should remain stationary and on the pad at all times.','Lower the handles slowly back to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Machine_Preacher_Curls/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Machine_Preacher_Curls/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Machine_Preacher_Curls/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('One Arm Dumbbell Preacher Curl','one-arm-dumbbell-preacher-curl','Ejercicio de tirón, aislamiento.',ARRAY['Grab a dumbbell with the right arm and place the upper arm on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.','As you breathe in, slowly lower the dumbbell until your upper arm is extended and the biceps is fully stretched.','As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbell is at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.','Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.','Switch arms and repeat the movement.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One_Arm_Dumbbell_Preacher_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One_Arm_Dumbbell_Preacher_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One_Arm_Dumbbell_Preacher_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Overhead Cable Curl','overhead-cable-curl','Ejercicio de tirón, aislamiento.',ARRAY['To begin, set a weight that is comfortable on each side of the pulley machine. Note: Make sure that the amount of weight selected is the same on each side.','Now adjust the height of the pulleys on each side and make sure that they are positioned at a height higher than that of your shoulders.','Stand in the middle of both sides and use an underhand grip (palms facing towards the ceiling) to grab each handle. Your arms should be fully extended and parallel to the floor with your feet positioned shoulder width apart from each other. Your body should be evenly aligned the handles. This is the starting position.','While exhaling, slowly squeeze the biceps on each side until your forearms and biceps touch.','While inhaling, move your forearms back to the starting position. Note: Your entire body is stationary during this exercise except for the forearms.','Repeat for the recommended amount of repetitions prescribed in your program.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Overhead_Cable_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Overhead_Cable_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Overhead_Cable_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Palms-Down Dumbbell Wrist Curl Over A Bench','palms-down-dumbbell-wrist-curl-over-a-bench','Ejercicio de tirón, aislamiento.',ARRAY['Start out by placing two dumbbells on one side of a flat bench.','Kneel down on both of your knees so that your body is facing the flat bench.','Use your arms to grab both of the dumbbells with a pronated grip (palms facing down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.','Start out by curling your wrist upwards and exhaling.','Slowly lower your wrists back down to the starting position while inhaling.','Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Palms-Down Wrist Curl Over A Bench','palms-down-wrist-curl-over-a-bench','Ejercicio de tirón, aislamiento.',ARRAY['Start out by placing a barbell on one side of a flat bench.','Kneel down on both of your knees so that your body is facing the flat bench.','Use your arms to grab the barbell with a pronated grip (palms down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.','Start out by curling your wrist upwards and exhaling.','Slowly lower your wrists back down to the starting position while inhaling.','Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Down_Wrist_Curl_Over_A_Bench/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Down_Wrist_Curl_Over_A_Bench/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Down_Wrist_Curl_Over_A_Bench/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Palms-Up Barbell Wrist Curl Over A Bench','palms-up-barbell-wrist-curl-over-a-bench','Ejercicio de tirón, aislamiento.',ARRAY['Start out by placing a barbell on one side of a flat bench.','Kneel down on both of your knees so that your body is facing the flat bench.','Use your arms to grab the barbell with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.','Start out by curling your wrist upwards and exhaling.','Slowly lower your wrists back down to the starting position while inhaling.','Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Alternating Cable Shoulder Press','alternating-cable-shoulder-press','Ejercicio de empuje, compuesto.',ARRAY['Move the cables to the bottom of the tower and select an appropriate weight.','Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.','Keeping your head and chest up, extend through the elbow to press one side directly over head.','After pausing at the top, return to the starting position and repeat on the opposite side.']::text[],'hombros',ARRAY['triceps']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Cable_Shoulder_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Cable_Shoulder_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Cable_Shoulder_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Alternating Kettlebell Press','alternating-kettlebell-press','Ejercicio de empuje, compuesto.',ARRAY['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.','Press one directly overhead by extending through the elbow, turning it so the palm faces forward while holding the other kettlebell stationary .','Lower the pressed kettlebell to the starting position and immediately press with your other arm.']::text[],'hombros',ARRAY['triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Kettlebell_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Kettlebell_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Kettlebell_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Anti-Gravity Press','anti-gravity-press','Ejercicio de empuje, compuesto.',ARRAY['Place a bar on the ground behind the head of an incline bench.','Lay on the bench face down. With a pronated grip, pick the barbell up from the floor. Flex the elbows, performing a reverse curl to bring the bar near your chest. This will be your starting position.','To begin, press the barbell out in front of your head by extending your elbows. Keep your arms parallel to the ground throughout the movement.','Return to the starting position and repeat to complete the set.']::text[],'hombros',ARRAY['espalda','triceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Anti-Gravity_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Anti-Gravity_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Anti-Gravity_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Arnold Dumbbell Press','arnold-dumbbell-press','Ejercicio de empuje, compuesto.',ARRAY['Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.','Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.','Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement.','After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Tip: The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Breathe in as you perform this portion of the movement.','Repeat for the recommended amount of repetitions.']::text[],'hombros',ARRAY['triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Arnold_Dumbbell_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Arnold_Dumbbell_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Arnold_Dumbbell_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Back Flyes - With Bands','back-flyes-with-bands','Ejercicio de tirón, compuesto.',ARRAY['Run a band around a stationary post like that of a squat rack.','Grab the band by the handles and stand back so that the tension in the band rises.','Extend and lift the arms straight in front of you. Tip: Your arms should be straight and parallel to the floor while perpendicular to your torso. Your feet should be firmly planted on the floor spread at shoulder width. This will be your starting position.','As you exhale, move your arms to the sides and back. Keep your arms extended and parallel to the floor. Continue the movement until the arms are extended to your sides.','After a pause, go back to the original position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'hombros',ARRAY['espalda','triceps']::muscle_group_type[],ARRAY['bandas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Back_Flyes_-_With_Bands/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Back_Flyes_-_With_Bands/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Back_Flyes_-_With_Bands/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Barbell Incline Shoulder Raise','barbell-incline-shoulder-raise','Ejercicio de empuje, compuesto.',ARRAY['Lie back on an Incline Bench. Using a medium width grip (a grip that is slightly wider than shoulder width), lift the bar from the rack and hold it straight over you with your arms straight. This will be your starting position.','While keeping the arms straight, lift the bar by protracting your shoulder blades, raising the shoulders from the bench as you breathe out.','Bring back the bar to the starting position as you breathe in.','Repeat for the recommended amount of repetitions.']::text[],'hombros',ARRAY['pecho']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Incline_Shoulder_Raise/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Incline_Shoulder_Raise/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Incline_Shoulder_Raise/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Barbell Rear Delt Row','barbell-rear-delt-row','Ejercicio de tirón, compuesto.',ARRAY['Stand up straight while holding a barbell using a wide (higher than shoulder width) and overhand (palms facing your body) grip.','Bend knees slightly and bend over as you keep the natural arch of your back. Let the arms hang in front of you as they hold the bar. Once your torso is parallel to the floor, flare the elbows out and away from your body. Tip: Your torso and your arms should resemble the letter "T". Now you are ready to begin the exercise.','While keeping the upper arms perpendicular to the torso, pull the barbell up towards your upper chest as you squeeze the rear delts and you breathe out. Tip: When performed correctly, this exercise should resemble a bench press in reverse. Also, refrain from using your biceps to do the work. Focus on targeting the rear delts; the arms should only act as hooks.','Slowly go back to the initial position as you breathe in.','Repeat for the recommended amount of repetitions.']::text[],'hombros',ARRAY['biceps','espalda']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Rear_Delt_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Rear_Delt_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Rear_Delt_Row/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Barbell Shoulder Press','barbell-shoulder-press','Ejercicio de empuje, compuesto.',ARRAY['Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward).','Once you pick up the barbell with the correct grip width, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.','Lower the bar down to the shoulders slowly as you inhale.','Lift the bar back up to the starting position as you exhale.','Repeat for the recommended amount of repetitions.']::text[],'hombros',ARRAY['pecho','triceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Shoulder_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Shoulder_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Shoulder_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Bradford/Rocky Presses','bradford-rocky-presses','Ejercicio de empuje, compuesto.',ARRAY['Sit on a Military Press Bench with a bar at shoulder level with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down. This is your starting position.','Once you pick up the barbell with the correct grip, lift the bar up over your head by locking your arms.','Now lower the bar down to the back of the head slowly as you inhale.','Lift the bar back up to the starting position as you exhale.','Lower the bar down to the starting position slowly as you inhale. This is one repetition.','Alternate in this manner until you complete the recommended amount of repetitions.']::text[],'hombros',ARRAY['triceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bradford_Rocky_Presses/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bradford_Rocky_Presses/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bradford_Rocky_Presses/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cable Internal Rotation','cable-internal-rotation','Ejercicio de tirón, compuesto.',ARRAY['Sit next to a low pulley sideways (with legs stretched in front of you or crossed) and grasp the single hand cable attachment with the arm nearest to the cable. Tip: If you can adjust the pulley''s height, you can use a flat bench to sit on instead.','Position the elbow against your side with the elbow bent at 90° and the arm pointing towards the pulley. This will be your starting position.','Pull the single hand cable attachment toward your body by internally rotating your shoulder until your forearm is across your abs. You will be creating an imaginary semi-circle. Tip: The forearm should be perpendicular to your torso at all times.','Slowly go back to the initial position.','Repeat for the recommended amount of repetitions and then repeat the movement with the next arm.']::text[],'hombros',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Internal_Rotation/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Internal_Rotation/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Internal_Rotation/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cable Rope Rear-Delt Rows','cable-rope-rear-delt-rows','Ejercicio de tirón, compuesto.',ARRAY['Sit in the same position on a low pulley row station as you would if you were doing seated cable rows for the back.','Attach a rope to the pulley and grasp it with an overhand grip. Your arms should be extended and parallel to the floor with the elbows flared out.','Keep your lower back upright and slide your hips back so that your knees are slightly bent. This will be your starting position.','Pull the cable attachment towards your upper chest, just below the neck, as you keep your elbows up and out to the sides. Continue this motion as you exhale until the elbows travel slightly behind the back. Tip: Keep your upper arms horizontal, perpendicular to the torso and parallel to the floor throughout the motion.','Go back to the initial position where the arms are extended and the shoulders are stretched forward. Inhale as you perform this portion of the movement.','Repeat for the recommended amount of repetitions.']::text[],'hombros',ARRAY['biceps','espalda']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Rope_Rear-Delt_Rows/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Rope_Rear-Delt_Rows/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Rope_Rear-Delt_Rows/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cable Shoulder Press','cable-shoulder-press','Ejercicio de empuje, compuesto.',ARRAY['Move the cables to the bottom of the towers and select an appropriate weight.','Stand directly in between the uprights. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.','Keeping your head and chest up, extend through the elbow to press the handles directly over head.','After pausing at the top, return to the starting position and repeat.']::text[],'hombros',ARRAY['triceps']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Shoulder_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Shoulder_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Shoulder_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Clean and Press','clean-and-press','Ejercicio de empuje, compuesto.',ARRAY['Assume a shoulder-width stance, with knees inside the arms. Now while keeping the back flat, bend at the knees and hips so that you can grab the bar with the arms fully extended and a pronated grip that is slightly wider than shoulder width. Point the elbows out to sides. The bar should be close to the shins. Position the shoulders over or slightly ahead of the bar. Establish a flat back posture. This will be your starting position.','Begin to pull the bar by extending the knees. Move your hips forward and raise the shoulders at the same rate while keeping the angle of the back constant; continue to lift the bar straight up while keeping it close to your body.','As the bar passes the knee, extend at the ankles, knees, and hips forcefully, similar to a jumping motion. As you do so, continue to guide the bar with your hands, shrugging your shoulders and using the momentum from your movement to pull the bar as high as possible. The bar should travel close to your body, and you should keep your elbows out.','At maximum elevation, your feet should clear the floor and you should start to pull yourself under the bar. The mechanics of this could change slightly, depending on the weight used. You should descend into a squatting position as you pull yourself under the bar.','As the bar hits terminal height, rotate your elbows around and under the bar. Rack the bar across the front of the shoulders while keeping the torso erect and flexing the hips and knees to absorb the weight of the bar.','Stand to full height, holding the bar in the clean position.','Without moving your feet, press the bar overhead as you exhale. Lower the bar under control .']::text[],'hombros',ARRAY['abdomen','piernas','gluteos','espalda','triceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean_and_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean_and_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean_and_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Cuban Press','cuban-press','Ejercicio de empuje, compuesto.',ARRAY['Take a dumbbell in each hand with a pronated grip in a standing position. Raise your upper arms so that they are parallel to the floor, allowing your lower arms to hang in the "scarecrow" position. This will be your starting position.','To initiate the movement, externally rotate the shoulders to move the upper arm 180 degrees. Keep the upper arms in place, rotating the upper arms until the wrists are directly above the elbows, the forearms perpendicular to the floor.','Now press the dumbbells by extending at the elbows, straightening your arms overhead.','Return to the starting position as you breathe in by reversing the steps.','Repeat for the recommended amount of repetitions.']::text[],'hombros',ARRAY['espalda']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cuban_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cuban_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cuban_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Double Kettlebell Jerk','double-kettlebell-jerk','Ejercicio de empuje, compuesto.',ARRAY['Hold a kettlebell by the handle in each hand.','Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. This will be your starting position.','Dip your body by bending the knees, keeping your torso upright.','Immediately reverse direction, driving through the heels, in essence jumping to create momentum.','As you do so, press the kettlebells overhead to lockout by extending the arms, using your body''s momentum to move the weights.','Return your feet to the ground in a split fashion, with one foot forward and one foot back.','Keeping the weights overhead, return to a standing position, bringing your feet together. Lower the weights to perform the next repetition.']::text[],'hombros',ARRAY['piernas','triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Double_Kettlebell_Jerk/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Double_Kettlebell_Jerk/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Double_Kettlebell_Jerk/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Double Kettlebell Push Press','double-kettlebell-push-press','Ejercicio de empuje, compuesto.',ARRAY['Clean two kettlebells to your shoulders.','Squat down a few inches and reverse the motion rapidly. Use the momentum from the legs to drive the kettlebells overhead.','Once the kettlebells are locked out, lower the kettlebells to your shoulders and repeat.']::text[],'hombros',ARRAY['piernas','triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Double_Kettlebell_Push_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Double_Kettlebell_Push_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Double_Kettlebell_Push_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Dumbbell One-Arm Shoulder Press','dumbbell-one-arm-shoulder-press','Ejercicio de empuje, compuesto.',ARRAY['Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.','Clean the dumbbell up to bring it to shoulder height. The other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface.','Rotate the wrist so that the palm of your hand is facing forward. This is your starting position.','As you exhale, push the dumbbell up until your arm is fully extended.','After a second pause, slowly come down back to the starting position as you inhale.','Repeat for the recommended amount of repetitions and then switch arms.']::text[],'hombros',ARRAY['triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_One-Arm_Shoulder_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_One-Arm_Shoulder_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_One-Arm_Shoulder_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Dumbbell One-Arm Upright Row','dumbbell-one-arm-upright-row','Ejercicio de tirón, compuesto.',ARRAY['Grab a dumbbell and stand up straight with your arm extended in front of you with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be resting on top of your thigh with the palm of your hands facing your thighs.','Keep the other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface. This will be your starting position.','Use your side shoulders to lift the dumbbell as you exhale. The dumbbell should be close to the body as you move it up. Continue to lift it until the dumbbell is nearly in line with your chin. Tip: Your elbows should drive the motion. As you lift the dumbbell, your elbow should always be higher than your forearm. Also, keep your torso stationary and pause for a second at the top of the movement.','Lower the dumbbell back down slowly to the starting position. Inhale as you perform this portion of the movement.','Repeat for the recommended amount of repetitions and switch arms.']::text[],'hombros',ARRAY['biceps','espalda']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_One-Arm_Upright_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_One-Arm_Upright_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_One-Arm_Upright_Row/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Dumbbell Raise','dumbbell-raise','Ejercicio de tirón, compuesto.',ARRAY['Grab a dumbbell in each arm and stand up straight with your arms extended by your sides with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be next to your thighs with the palm of your hands facing back.','Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be to the side of the body as you move them up. Continue to lift it until the dumbbells are nearly in line with your chin. Tip: Your elbows should drive the motion. As you lift the dumbbell, your elbow should always be higher than your forearm. Also, keep your torso stationary and pause for a second at the top of the movement.','Lower the dumbbells back down slowly to the starting position. Inhale as you perform this portion of the movement.','Repeat for the recommended amount of repetitions.']::text[],'hombros',ARRAY['biceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Raise/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Raise/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Raise/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Dumbbell Shoulder Press','dumbbell-shoulder-press','Ejercicio de empuje, compuesto.',ARRAY['While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.','Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.','Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.','Now, exhale and push the dumbbells upward until they touch at the top.','Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.','Repeat for the recommended amount of repetitions.']::text[],'hombros',ARRAY['triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Shoulder_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Shoulder_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Shoulder_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('External Rotation with Band','external-rotation-with-band','Ejercicio de tirón, compuesto.',ARRAY['Choke the band around a post. The band should be at the same height as your elbow. Stand with your left side to the band a couple of feet away.','Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.','With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.','Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.','Continue as far as you are able, pause, and then return to the starting position.']::text[],'hombros',ARRAY[]::muscle_group_type[],ARRAY['bandas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/External_Rotation_with_Band/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/External_Rotation_with_Band/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/External_Rotation_with_Band/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Face Pull','face-pull','Ejercicio de tirón, compuesto.',ARRAY['Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground.']::text[],'hombros',ARRAY['espalda']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Face_Pull/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Face_Pull/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Face_Pull/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Iron Cross','iron-cross','Ejercicio de empuje, compuesto.',ARRAY[]::text[],'hombros',ARRAY['pecho','gluteos','piernas','espalda']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Iron_Cross/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Iron_Cross/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Iron_Cross/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Jerk Balance','jerk-balance','Ejercicio de empuje, compuesto.',ARRAY['This drill helps you learn to drive yourself low enough during the jerk and corrects those who move backward during the movement. Begin with the bar racked in the jerk position, with the shoulders forward, torso upright, and the feet split slightly apart.','Initiate the movement as you would a normal jerk, dipping at the knees while keeping your torso vertical, and driving back up forcefully, using momentum and not your arms to elevate the weight.','Keep the rear foot in place, using it to drive your body forward into a full split as you jerk the weight. Recover by standing up with the weight overhead.']::text[],'hombros',ARRAY['gluteos','piernas','triceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Jerk_Balance/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Jerk_Balance/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Jerk_Balance/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Kettlebell Arnold Press','kettlebell-arnold-press','Ejercicio de empuje, compuesto.',ARRAY['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you raise the kettlebell towards your shoulder. The palm should be facing inward.','Looking straight ahead, press the kettlebell out and overhead, rotating your wrist so that your palm faces forward at the top of the motion.','Return the kettlebell to the starting position, with the palm facing in.']::text[],'hombros',ARRAY['triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Arnold_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Arnold_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Arnold_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Kettlebell Pirate Ships','kettlebell-pirate-ships','Ejercicio de empuje, compuesto.',ARRAY['With a wide stance, hold a kettlebell with both hands. Allow it to hang at waist level with your arms extended. This will be your starting position.','Initiate the movement by turning to one side, swinging the kettlebell to head height. Briefly pause at the top of the motion.','Allow the bell to drop as you rotate to the opposite side, again raising the kettlebell to head height.','Repeat for the desired amount of repetitions.']::text[],'hombros',ARRAY['abdomen']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Pirate_Ships/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Pirate_Ships/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Pirate_Ships/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Kettlebell Seated Press','kettlebell-seated-press','Ejercicio de empuje, compuesto.',ARRAY['Sit on the floor and spread your legs out comfortably.','Clean one kettlebell to your shoulder.','Press the kettlebell up and out until it is locked out overhead. Return to the starting position.']::text[],'hombros',ARRAY['triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Seated_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Seated_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Seated_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Kettlebell Seesaw Press','kettlebell-seesaw-press','Ejercicio de empuje, compuesto.',ARRAY['Clean two kettlebells two your shoulders.','Press one kettlebell.','Lower the kettlebell and immediately press the other kettlebell. Make sure to do the same amount of reps on both sides.']::text[],'hombros',ARRAY['triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Seesaw_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Seesaw_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Seesaw_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Kettlebell Thruster','kettlebell-thruster','Ejercicio de empuje, compuesto.',ARRAY['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so. This will be your starting position.','Begin to squat by flexing your hips and knees, lowering your hips between your legs. Maintain an upright, straight back as you descend as low as you can.','At the bottom, reverse direction and squat by extending your knees and hips, driving through your heels. As you do so, press both kettlebells overhead by extending your arms straight up, using the momentum from the squat to help drive the weights upward.','As you begin the next repetition, return the weights to the shoulders.']::text[],'hombros',ARRAY['piernas','triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Thruster/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Thruster/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Thruster/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Kettlebell Turkish Get-Up (Lunge style)','kettlebell-turkish-get-up-lunge-style','Ejercicio de empuje, compuesto.',ARRAY['Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell.','Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position. Using your free hand, push yourself to a seated position, then progressing to one knee.','While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position and repeat.']::text[],'hombros',ARRAY['abdomen','piernas','triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Turkish_Get-Up_Lunge_style/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Turkish_Get-Up_Lunge_style/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Turkish_Get-Up_Lunge_style/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Kettlebell Turkish Get-Up (Squat style)','kettlebell-turkish-get-up-squat-style','Ejercicio de empuje, compuesto.',ARRAY['Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell.','Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position.','Using your free hand, push yourself to a seated position, then progressing to your feet. While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position and repeat.']::text[],'hombros',ARRAY['abdomen','piernas','triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Turkish_Get-Up_Squat_style/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Turkish_Get-Up_Squat_style/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Turkish_Get-Up_Squat_style/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Landmine Linear Jammer','landmine-linear-jammer','Ejercicio de empuje, compuesto.',ARRAY['Position a bar into landmine or, lacking one, securely anchor it in a corner. Load the bar to an appropriate weight and position the handle attachment on the bar.','Raise the bar from the floor, taking the handles to your shoulders. This will be your starting position.','In an athletic stance, squat by flexing your hips and setting your hips back, keeping your arms flexed.','Reverse the motion by powerfully extending through the hips, knees, and ankles, while also extending the elbows to straighten the arms. This movement should be done explosively, coming out of the squat to full extension as powerfully as possible.','Return to the starting position.']::text[],'hombros',ARRAY['abdomen','piernas','pecho','triceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Landmine_Linear_Jammer/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Landmine_Linear_Jammer/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Landmine_Linear_Jammer/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Leverage Shoulder Press','leverage-shoulder-press','Ejercicio de empuje, compuesto.',ARRAY['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the shoulders at the beginning of the motion. Your chest and head should be up and handles held with a pronated grip. This will be your starting position.','Press the handles upward by extending through the elbow.','After a brief pause at the top, return the weight to just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.']::text[],'hombros',ARRAY['triceps']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leverage_Shoulder_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leverage_Shoulder_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leverage_Shoulder_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Low Pulley Row To Neck','low-pulley-row-to-neck','Ejercicio de tirón, compuesto.',ARRAY['Sit on a low pulley row machine with a rope attachment.','Grab the ends of the rope using a palms-down grip and sit with your back straight and your knees slightly bent. Tip: Keep your back almost completely vertical and your arms fully extended in front of you. This will be your starting position.','While keeping your torso stationary, lift your elbows and start bending them as you pull the rope towards your neck while exhaling. Throughout the movement your upper arms should remain parallel to the floor. Tip: Continue this motion until your hands are almost next to your ears (the forearms will not be parallel to the floor at the end of the movement as they will be angled a bit upwards) and your elbows are out away from your sides.','After holding for a second or so at the contracted position, come back slowly to the starting position as you inhale. Tip: Again, during no part of the movement should the torso move.','Repeat for the recommended amount of repetitions.']::text[],'hombros',ARRAY['biceps','espalda']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Low_Pulley_Row_To_Neck/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Low_Pulley_Row_To_Neck/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Low_Pulley_Row_To_Neck/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Machine Shoulder (Military) Press','machine-shoulder-military-press','Ejercicio de empuje, compuesto.',ARRAY['Sit down on the Shoulder Press Machine and select the weight.','Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position.','Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second.','Lower the handles slowly back to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'hombros',ARRAY['triceps']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Machine_Shoulder_Military_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Machine_Shoulder_Military_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Machine_Shoulder_Military_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('One-Arm Kettlebell Clean and Jerk','one-arm-kettlebell-clean-and-jerk','Ejercicio de empuje, compuesto.',ARRAY['Hold a kettlebell by the handle.','Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward.','Dip your body by bending the knees, keeping your torso upright.','Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight.','Receive the weight overhead by returning to a squat position underneath the weight.','Keeping the weight overhead, return to a standing position. Lower the weight to the floor to perform the next repetition.']::text[],'hombros',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Arm_Kettlebell_Clean_and_Jerk/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Arm_Kettlebell_Clean_and_Jerk/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Arm_Kettlebell_Clean_and_Jerk/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('One-Arm Kettlebell Jerk','one-arm-kettlebell-jerk','Ejercicio de empuje, compuesto.',ARRAY['Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.','Dip your body by bending the knees, keeping your torso upright.','Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight. Receive the weight overhead by returning to a squat position underneath the weight. Keeping the weight overhead, return to a standing position.','Lower the weight to perform the next repetition.']::text[],'hombros',ARRAY['piernas','triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Arm_Kettlebell_Jerk/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Arm_Kettlebell_Jerk/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Arm_Kettlebell_Jerk/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('One-Arm Kettlebell Military Press To The Side','one-arm-kettlebell-military-press-to-the-side','Ejercicio de empuje, compuesto.',ARRAY['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces inward. This will be your starting position.','Look at the kettlebell and press it up and out until it is locked out overhead.','Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength.']::text[],'hombros',ARRAY['triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Arm_Kettlebell_Military_Press_To_The_Side/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Arm_Kettlebell_Military_Press_To_The_Side/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Arm_Kettlebell_Military_Press_To_The_Side/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Alternating Floor Press','alternating-floor-press','Ejercicio de empuje, compuesto.',ARRAY['Lie on the floor with two kettlebells next to your shoulders.','Position one in place on your chest and then the other, gripping the kettlebells on the handle with the palms facing forward.','Extend both arms, so that the kettlebells are being held above your chest. Lower one kettlebell, bringing it to your chest and turn the wrist in the direction of the locked out kettlebell.','Raise the kettlebell and repeat on the opposite side.']::text[],'pecho',ARRAY['abdomen','hombros','triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Floor_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Floor_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Floor_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Around The Worlds','around-the-worlds','Ejercicio de empuje, compuesto.',ARRAY['Lay down on a flat bench holding a dumbbell in each hand with the palms of the hands facing towards the ceiling. Tip: Your arms should be parallel to the floor and next to your thighs. To avoid injury, make sure that you keep your elbows slightly bent. This will be your starting position.','Now move the dumbbells by creating a semi-circle as you displace them from the initial position to over the head. All of the movement should happen with the arms parallel to the floor at all times. Breathe in as you perform this portion of the movement.','Reverse the movement to return the weight to the starting position as you exhale.']::text[],'pecho',ARRAY['hombros']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Around_The_Worlds/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Around_The_Worlds/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Around_The_Worlds/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Barbell Bench Press - Medium Grip','barbell-bench-press-medium-grip','Ejercicio de empuje, compuesto.',ARRAY['Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.','After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Bench_Press_-_Medium_Grip/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Barbell Guillotine Bench Press','barbell-guillotine-bench-press','Ejercicio de empuje, compuesto.',ARRAY['Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.','As you breathe in, bring the bar down slowly until it is about 1 inch from your neck.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Guillotine_Bench_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Guillotine_Bench_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Guillotine_Bench_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Barbell Incline Bench Press - Medium Grip','barbell-incline-bench-press-medium-grip','Ejercicio de empuje, compuesto.',ARRAY['Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','As you breathe in, come down slowly until you feel the bar on you upper chest.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly again. Tip: it should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Bench Press - With Bands','bench-press-with-bands','Ejercicio de empuje, compuesto.',ARRAY['Using a flat bench secure a band under the leg of the bench that is nearest to your head.','Once the band is secure, grab it by both handles and lie down on the bench.','Extend your arms so that you are holding the band handles in front of you at shoulder width.','Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.','Bring down the handles slowly until your elbow forms a 90 degree angle. Keep full control at all times.','As you breathe out, bring the handles up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions of your training program.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['bandas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Press_-_With_Bands/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Press_-_With_Bands/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Press_-_With_Bands/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Bent-Arm Dumbbell Pullover','bent-arm-dumbbell-pullover','Ejercicio de empuje, compuesto.',ARRAY['Place a dumbbell standing up on a flat bench.','Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.','Grasp the dumbbell with both hands and hold it straight over your chest with a bend in your arms. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position. Caution: Always ensure that the dumbbell used for this exercise is secure. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.','While keeping your arms locked in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.','At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.','Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.']::text[],'pecho',ARRAY['espalda','hombros','triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent-Arm_Dumbbell_Pullover/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent-Arm_Dumbbell_Pullover/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent-Arm_Dumbbell_Pullover/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Cable Chest Press','cable-chest-press','Ejercicio de empuje, compuesto.',ARRAY['Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.','Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.','After pausing at full extension, return to th starting position, keeping tension on the cables.','You can also execute this movement with your back off the pad, at an incline or decline, or alternate hands.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Chest_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Chest_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Chest_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Clock Push-Up','clock-push-up','Ejercicio de empuje, compuesto.',ARRAY['Move into a prone position on the floor, supporting your weight on your hands and toes.','Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position.','Descend by flexing at the elbow, lowering your chest toward the ground.','At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible until you are air borne. Aim to "jump" 12-18 inches to one side.','As you accelerate up, move your outside foot away from your direction of travel. Leaving the ground, shift your body about 30 degrees for the next repetition.','Return to the starting position and repeat the exercise, working all the way around until you are back where you started.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clock_Push-Up/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clock_Push-Up/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clock_Push-Up/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Cross Over - With Bands','cross-over-with-bands','Ejercicio de empuje, compuesto.',ARRAY['Secure an exercise band around a stationary post.','While facing away from the post, grab the handles on both ends of the band and step forward enough to create tension on the band.','Raise your arms to the sides, parallel to the floor, perpendicular to your torso (your torso and the arms should resemble the letter "T") and with the palms facing forward. Have them extended with a slight bend at the elbows. This will be your starting position.','While keeping your arms straight, bring them across your chest in a semicircular motion to the front as you exhale and flex your pecs. Hold the contraction for a second.','Slowly return to the starting position as you inhale.','Perform for the recommended amount of repetitions.']::text[],'pecho',ARRAY['biceps','hombros']::muscle_group_type[],ARRAY['bandas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cross_Over_-_With_Bands/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cross_Over_-_With_Bands/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cross_Over_-_With_Bands/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Decline Barbell Bench Press','decline-barbell-bench-press','Ejercicio de empuje, compuesto.',ARRAY['Secure your legs at the end of the decline bench and slowly lay down on the bench.','Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.','As you breathe in, come down slowly until you feel the bar on your lower chest.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Barbell_Bench_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Barbell_Bench_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Barbell_Bench_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Decline Dumbbell Bench Press','decline-dumbbell-bench-press','Ejercicio de empuje, compuesto.',ARRAY['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.','Once you are laying down, move the dumbbells in front of you at shoulder width.','Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.','Bring down the weights slowly to your side as you breathe out. Keep full control of the dumbbells at all times. Tip: Throughout the motion, the forearms should always be perpendicular to the floor.','As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up..','Repeat the movement for the prescribed amount of repetitions of your training program.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Dumbbell_Bench_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Dumbbell_Bench_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Dumbbell_Bench_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Decline Dumbbell Flyes','decline-dumbbell-flyes','Ejercicio de empuje, compuesto.',ARRAY['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.','Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.','With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.','Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.','Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.']::text[],'pecho',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Dumbbell_Flyes/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Dumbbell_Flyes/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Dumbbell_Flyes/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Decline Smith Press','decline-smith-press','Ejercicio de empuje, compuesto.',ARRAY['Place a decline bench underneath the Smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms extended. This will be your starting position.','As you inhale, lower the bar under control by allowing the elbows to flex, lightly contacting the torso.','After a brief pause, bring the bar back to the starting position by extending the elbows, exhaling as you do so.','Repeat the movement for the prescribed amount of repetitions.','When the set is complete, lock the bar back in the rack.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Smith_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Smith_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Smith_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Dumbbell Bench Press','dumbbell-bench-press','Ejercicio de empuje, compuesto.',ARRAY['Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.','Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.','Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.','Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.','Repeat the movement for the prescribed amount of repetitions of your training program.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Bench_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Bench_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Bench_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Dumbbell Bench Press with Neutral Grip','dumbbell-bench-press-with-neutral-grip','Ejercicio de empuje, compuesto.',ARRAY['Take a dumbbell in each hand and lay back onto a flat bench. Your feet should be flat on the floor and your shoulder blades retracted.','Maintaining a neutral grip, palms facing each other, begin with your arms extended directly above you, perpendicular to the floor. This will be your starting position.','Begin the movement by flexing the elbow, lowering the upper arms to the side. Descend until the dumbbells are to your torso.','Pause, then extend the elbow and return to the starting position.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Bench_Press_with_Neutral_Grip/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Bench_Press_with_Neutral_Grip/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Bench_Press_with_Neutral_Grip/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Extended Range One-Arm Kettlebell Floor Press','extended-range-one-arm-kettlebell-floor-press','Ejercicio de empuje, compuesto.',ARRAY['Lie on the floor and position a kettlebell for one arm to press. The kettlebell should be held by the handle. The leg on the same side that you are pressing should be bent, with the knee crossing over the midline of the body.','Press the kettlebell by extending the elbow and adducting the arm, pressing it above your body. Return to the starting position.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Extended_Range_One-Arm_Kettlebell_Floor_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Extended_Range_One-Arm_Kettlebell_Floor_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Extended_Range_One-Arm_Kettlebell_Floor_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Front Raise And Pullover','front-raise-and-pullover','Ejercicio de tirón, compuesto.',ARRAY['Lie on a flat bench while holding a barbell using a palms down grip that is about 15 inches apart.','Place the bar on your upper thighs, extend your arms and lock them while keeping a slight bend on the elbows. This will be your starting position.','Now raise the weight using a semicircular motion and keeping your arms straight as you inhale. Continue the same movement until the bar is on the other side above your head . (Tip: the bar will travel approximately 180-degrees). At this point your arms should be parallel to the floor with the palms of your hands facing the ceiling.','Now return the barbell to the starting position by reversing the motion as you exhale.','Repeat for the recommended amount of repetitions.']::text[],'pecho',ARRAY['espalda','hombros','triceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Front_Raise_And_Pullover/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Front_Raise_And_Pullover/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Front_Raise_And_Pullover/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Hammer Grip Incline DB Bench Press','hammer-grip-incline-db-bench-press','Ejercicio de empuje, compuesto.',ARRAY['Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.','By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.','Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.','Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.','As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the dumbbells back in your thighs and then on the floor. This is the safest manner to dispose of the dumbbells.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hammer_Grip_Incline_DB_Bench_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hammer_Grip_Incline_DB_Bench_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hammer_Grip_Incline_DB_Bench_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Incline Cable Chest Press','incline-cable-chest-press','Ejercicio de empuje, compuesto.',ARRAY['Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.','Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.','After pausing at full extension, return to the starting position, keeping tension on the cables.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Cable_Chest_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Cable_Chest_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Cable_Chest_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Incline Dumbbell Bench With Palms Facing In','incline-dumbbell-bench-with-palms-facing-in','Ejercicio de empuje, compuesto.',ARRAY['Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.','By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.','Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.','Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.','As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the dumbbells back in your thighs and then on the floor. This is the safest manner to dispose of the dumbbells.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Dumbbell_Bench_With_Palms_Facing_In/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Dumbbell_Bench_With_Palms_Facing_In/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Dumbbell_Bench_With_Palms_Facing_In/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Incline Dumbbell Flyes','incline-dumbbell-flyes','Ejercicio de empuje, compuesto.',ARRAY['Hold a dumbbell on each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.','Extend your arms above you with a slight bend at the elbows.','Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.','As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.','As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.','Repeat for the recommended amount of repetitions.']::text[],'pecho',ARRAY['hombros']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Dumbbell_Flyes/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Dumbbell_Flyes/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Dumbbell_Flyes/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Incline Dumbbell Flyes - With A Twist','incline-dumbbell-flyes-with-a-twist','Ejercicio de empuje, compuesto.',ARRAY['Hold a dumbbell in each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.','Extend your arms above you with a slight bend at the elbows.','Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.','As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.','As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.','Repeat for the recommended amount of repetitions.']::text[],'pecho',ARRAY['hombros']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Dumbbell_Flyes_-_With_A_Twist/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Dumbbell_Flyes_-_With_A_Twist/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Dumbbell_Flyes_-_With_A_Twist/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Incline Dumbbell Press','incline-dumbbell-press','Ejercicio de empuje, compuesto.',ARRAY['Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.','Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.','Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.','Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.','Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Dumbbell_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Dumbbell_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Dumbbell_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Incline Push-Up','incline-push-up','Ejercicio de empuje, compuesto.',ARRAY['Stand facing bench or sturdy elevated platform. Place hands on edge of bench or platform, slightly wider than shoulder width.','Position forefoot back from bench or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower chest to edge of box or platform by bending arms.','Push body up until arms are extended. Repeat.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Push-Up/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Push-Up/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Push-Up/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Incline Push-Up Medium','incline-push-up-medium','Ejercicio de empuje, compuesto.',ARRAY['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.','Place your hands on the bar, with your hands about shoulder width apart.','Position your feet back from the bar with arms and body straight. This will be your starting position.','Keeping your body straight, lower your chest to the bar by bending the arms.','Return to the starting position by extending the elbows, pressing yourself back up.']::text[],'pecho',ARRAY['abdomen','hombros','triceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Push-Up_Medium/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Push-Up_Medium/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Push-Up_Medium/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Incline Push-Up Reverse Grip','incline-push-up-reverse-grip','Ejercicio de empuje, compuesto.',ARRAY['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.','Place your hands on the bar palms up, with your hands about shoulder width apart.','Position your feet back from the bar with arms and body straight. This will be your starting position.','Keeping your body straight, lower your chest to the bar by bending the arms.','Return to the starting position by extending the elbows, pressing yourself back up.']::text[],'pecho',ARRAY['abdomen','hombros','triceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Push-Up_Reverse_Grip/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Push-Up_Reverse_Grip/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Push-Up_Reverse_Grip/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Incline Push-Up Wide','incline-push-up-wide','Ejercicio de empuje, compuesto.',ARRAY['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.','Place your hands on the bar, with your hands wider than shoulder width.','Position your feet back from the bar with arms and body straight. Your arms should be perpendicular to the body. This will be your starting position.','Keeping your body straight, lower your chest to the bar by bending the arms.','Return to the starting position by extending the elbows, pressing yourself back up.']::text[],'pecho',ARRAY['abdomen','hombros','triceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Push-Up_Wide/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Push-Up_Wide/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Push-Up_Wide/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Isometric Chest Squeezes','isometric-chest-squeezes','Ejercicio de estático, compuesto.',ARRAY['While either seating or standing, bend your arms at a 90-degree angle and place the palms of your hands together in front of your chest. Tip: Your hands should be open with the palms together and fingers facing forward (perpendicular to your torso).','Push both hands against each other as you contract your chest. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.','Hold for the recommended number of seconds.','Now release the tension slowly.','Rest for the recommended amount of time and repeat.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Isometric_Chest_Squeezes/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Isometric_Chest_Squeezes/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Isometric_Chest_Squeezes/1.jpg']::text[],'Estático','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Isometric Wipers','isometric-wipers','Ejercicio de empuje, compuesto.',ARRAY['Assume a push-up position, supporting your weight on your hands and toes while keeping your body straight. Your hands should be just outside of shoulder width. This will be your starting position.','Begin by shifting your body weight as far to one side as possible, allowing the elbow on that side to flex as you lower your body.','Reverse the motion by extending the flexed arm, pushing yourself up and then dropping to the other side.','Repeat for the desired number of repetitions.']::text[],'pecho',ARRAY['abdomen','hombros','triceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Isometric_Wipers/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Isometric_Wipers/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Isometric_Wipers/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Leg-Over Floor Press','leg-over-floor-press','Ejercicio de empuje, compuesto.',ARRAY['Lie on the floor with one kettlebell in place on your chest, holding it by the handle. Extend leg on working side over leg on non-working side.Your free arm can be extended out to your side for support.','Press the kettlebll into a locked out position.','Lower the weight until the elbow touches the ground, keeping the kettlebell above the elbow. Repeat for the desired number of repetitions.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leg-Over_Floor_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leg-Over_Floor_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leg-Over_Floor_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Leverage Chest Press','leverage-chest-press','Ejercicio de empuje, compuesto.',ARRAY['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion.','Your chest and head should be up and your shoulder blades retracted. This will be your starting position.','Press the handles forward by extending through the elbow.','After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leverage_Chest_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leverage_Chest_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leverage_Chest_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Leverage Decline Chest Press','leverage-decline-chest-press','Ejercicio de empuje, compuesto.',ARRAY['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.','Press the handles forward by extending through the elbow.','After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leverage_Decline_Chest_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leverage_Decline_Chest_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leverage_Decline_Chest_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Leverage Incline Chest Press','leverage-incline-chest-press','Ejercicio de empuje, compuesto.',ARRAY['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.','Press the handles forward by extending through the elbow.','After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leverage_Incline_Chest_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leverage_Incline_Chest_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leverage_Incline_Chest_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Machine Bench Press','machine-bench-press','Ejercicio de empuje, compuesto.',ARRAY['Sit down on the Chest Press Machine and select the weight.','Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms.','Grab the handles with a palms-down grip and lift your elbows so that your upper arms are parallel to the floor to the sides of your torso. Tip: Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be at the starting position.','Now bring the handles back towards you as you breathe in.','Push the handles away from you as you flex your pecs and you breathe out. Hold the contraction for a second before going back to the starting position.','Repeat for the recommended amount of reps.','When finished step on the lever again and slowly get the handles back to their original place.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Machine_Bench_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Machine_Bench_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Machine_Bench_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Neck Press','neck-press','Ejercicio de empuje, compuesto.',ARRAY['Lie back on a flat bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.','As you breathe in, come down slowly until you feel the bar on your neck.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Neck_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Neck_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Neck_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('One-Arm Kettlebell Floor Press','one-arm-kettlebell-floor-press','Ejercicio de empuje, compuesto.',ARRAY['Lie on the floor holding a kettlebell with one hand, with your upper arm supported by the floor. The palm should be facing in.','Press the kettlebell straight up toward the ceiling, rotating your wrist.','Lower the kettlebell back to the starting position and repeat.']::text[],'pecho',ARRAY['triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Arm_Kettlebell_Floor_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Arm_Kettlebell_Floor_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Arm_Kettlebell_Floor_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('One Arm Dumbbell Bench Press','one-arm-dumbbell-bench-press','Ejercicio de empuje, compuesto.',ARRAY['Lie down on a flat bench with a dumbbell in one hand on top of your thigh.','By using your thigh to help you get the dumbbell up, clean the dumbbell up so that you can hold it in front of you at shoulder width. Use the hand you are not lifting with to help position the dumbbell over you properly.','Once at shoulder width, rotate your wrist forward so that the palm of your hand is facing away from you. This will be your starting position.','Bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbell at all times. Tip: Use the hand that you are not lifting with to help keep the dumbbell balance as you may struggle a bit at first. Only use your non-lifting hand if it is needed. Otherwise, keep it resting to the side.','As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions of your training program.','Switch arms and repeat the movement.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One_Arm_Dumbbell_Bench_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One_Arm_Dumbbell_Bench_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One_Arm_Dumbbell_Bench_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Alternating Hang Clean','alternating-hang-clean','Ejercicio de tirón, compuesto.',ARRAY['Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.','Clean one kettlebell to your shoulder and hold on to the other kettlebell in a hanging position. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so.','Lower the cleaned kettlebell to a hanging position and clean the alternate kettlebell. Repeat.']::text[],'piernas',ARRAY['biceps','gluteos','espalda']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Hang_Clean/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Hang_Clean/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Hang_Clean/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Band Good Morning','band-good-morning','Ejercicio de tirón, compuesto.',ARRAY['Using a 41 inch band, stand on one end, spreading your feet a small amount. Bend at the hips to loop the end of the band behind your neck. This will be your starting position.','Keeping your legs straight, extend through the hips to come to a near vertical position.','Ensure that you do not round your back as you go down back to the starting position.']::text[],'piernas',ARRAY['gluteos','espalda']::muscle_group_type[],ARRAY['bandas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Good_Morning/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Good_Morning/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Good_Morning/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Band Good Morning (Pull Through)','band-good-morning-pull-through','Ejercicio de tirón, compuesto.',ARRAY['Loop the band around a post. Standing a little ways away, loop the opposite end around the neck. Your hands can help hold the band in position.','Begin by bending at the hips, getting your butt back as far as possible. Keep your back flat and bend forward to about 90 degrees. Your knees should be only slightly bent.','Return to the starting position be driving through with the hips to come back to a standing position.']::text[],'piernas',ARRAY['gluteos','espalda']::muscle_group_type[],ARRAY['bandas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Good_Morning_Pull_Through/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Good_Morning_Pull_Through/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Good_Morning_Pull_Through/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Barbell Full Squat','barbell-full-squat','Ejercicio de empuje, compuesto.',ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a shoulder-width medium stance with the toes slightly pointed out. Keep your head up at all times and maintain a straight back. This will be your starting position.','Begin to slowly lower the bar by bending the knees and sitting back with your hips as you maintain a straight posture with the head up. Continue down until your hamstrings are on your calves. Inhale as you perform this portion of the movement.','Begin to raise the bar as you exhale by pushing the floor with the heel or middle of your foot as you straighten the legs and extend the hips to go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'piernas',ARRAY['gluteos','espalda']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Full_Squat/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Full_Squat/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Full_Squat/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Barbell Hack Squat','barbell-hack-squat','Ejercicio de empuje, compuesto.',ARRAY['Stand up straight while holding a barbell behind you at arms length and your feet at shoulder width. Tip: A shoulder width grip is best with the palms of your hands facing back. You can use wrist wraps for this exercise for a better grip. This will be your starting position.','While keeping your head and eyes up and back straight, squat until your upper thighs are parallel to the floor. Breathe in as you slowly go down.','Pressing mainly with the heel of the foot and squeezing the thighs, go back up as you breathe out.','Repeat for the recommended amount of repetitions.']::text[],'piernas',ARRAY['biceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Hack_Squat/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Hack_Squat/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Hack_Squat/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Barbell Lunge','barbell-lunge','Ejercicio de empuje, compuesto.',ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: Do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. li>','Using mainly the heel of your foot, push up and go back to the starting position as you exhale.','Repeat the movement for the recommended amount of repetitions and then perform with the left leg.']::text[],'piernas',ARRAY['gluteos']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Lunge/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Lunge/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Lunge/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Barbell Side Split Squat','barbell-side-split-squat','Ejercicio de empuje, compuesto.',ARRAY['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be placed wide apart with the foot of the lead leg angled out to the side. This will be your starting position.','Lower your body towards the side of your angled foot by bending the knee and hip of your lead leg and while keeping the opposite leg only slightly bent. Breathe in as you lower your body.','Return to the starting position by extending the hip and knee of the lead leg. Breathe out as you perform this movement.','After performing the recommended amount of reps, repeat the movement with the opposite leg.']::text[],'piernas',ARRAY['espalda']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Side_Split_Squat/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Side_Split_Squat/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Side_Split_Squat/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Barbell Squat','barbell-squat','Ejercicio de empuje, compuesto.',ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).','Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'piernas',ARRAY['gluteos','espalda']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Squat/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Squat/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Squat/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Barbell Step Ups','barbell-step-ups','Ejercicio de empuje, compuesto.',ARRAY['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck) and stand upright behind an elevated platform (such as the one used for spotting behind a flat bench). This is your starting position.','Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.','Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.','Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.']::text[],'piernas',ARRAY['gluteos']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Step_Ups/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Step_Ups/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Step_Ups/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Barbell Walking Lunge','barbell-walking-lunge','Ejercicio de empuje, compuesto.',ARRAY['Begin standing with your feet shoulder width apart and a barbell across your upper back.','Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.','Drive through the heel of your lead foot and extend both knees to raise yourself back up.','Step forward with your rear foot, repeating the lunge on the opposite leg.']::text[],'piernas',ARRAY['gluteos']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Walking_Lunge/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Walking_Lunge/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Walking_Lunge/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Bench Jump','bench-jump','Ejercicio de empuje, compuesto.',ARRAY['Begin with a box or bench 1-2 feet in front of you. Stand with your feet shoulder width apart. This will be your starting position.','Perform a short squat in preparation for the jump; swing your arms behind you.','Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.','Jump over the bench, landing with the knees bent, absorbing the impact through the legs.','Turn around and face the opposite direction, then jump back over the bench.']::text[],'piernas',ARRAY['gluteos']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Jump/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Jump/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Jump/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Bodyweight Squat','bodyweight-squat','Ejercicio de empuje, compuesto.',ARRAY['Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.','Begin the movement by flexing your knees and hips, sitting back with your hips.','Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out.']::text[],'piernas',ARRAY['gluteos']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bodyweight_Squat/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bodyweight_Squat/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bodyweight_Squat/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Box Squat','box-squat','Ejercicio de empuje, compuesto.',ARRAY['The box squat allows you to squat to desired depth and develop explosive strength in the squat movement. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.','Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.','With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.','Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe.']::text[],'piernas',ARRAY['gluteos','espalda']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Box_Squat/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Box_Squat/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Box_Squat/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Cable Deadlifts','cable-deadlifts','Ejercicio de tirón, compuesto.',ARRAY['Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights.','To begin, squat down be flexing your hips and knees until you can reach the handles.','After grasping them, begin your ascent. Driving through your heels extend your hips and knees keeping your hands hanging at your side. Keep your head and chest up throughout the movement.','After reaching a full standing position, Return to the starting position and repeat.']::text[],'piernas',ARRAY['biceps','gluteos','espalda']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Deadlifts/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Deadlifts/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Deadlifts/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Chair Squat','chair-squat','Ejercicio de empuje, compuesto.',ARRAY['To begin, first set the bar to a position that best matches your height. Once the bar is loaded, step under it and position it across the back of your shoulders.','Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs.','Move your feet forward about 18 inches in front of the bar. Position your legs using a shoulder width stance with the toes slightly pointed out. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position.','Slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper and lower leg breaks 90 degrees.','Begin to raise the bar as you exhale by pushing the floor with the heels of your feet, extending the knees and returning to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'piernas',ARRAY['gluteos']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chair_Squat/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chair_Squat/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chair_Squat/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Clean','clean','Ejercicio de tirón, compuesto.',ARRAY['With a barbell on the floor close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.','','Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.','Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.','As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.','Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.']::text[],'piernas',ARRAY['biceps','gluteos','espalda','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Clean Deadlift','clean-deadlift','Ejercicio de tirón, compuesto.',ARRAY['Begin standing with a barbell close to your shins. Your feet should be directly under your hips with your feet turned out slightly. Grip the bar with a double overhand grip or hook grip, about shoulder width apart. Squat down to the bar. Your spine should be in full extension, with a back angle that places your shoulders in front of the bar and your back as vertical as possible.','Begin by driving through the floor through the front of your heels. As the bar travels upward, maintain a constant back angle. Flare your knees out to the side to help keep them out of the bar''s path.','After the bar crosses the knees, complete the lift by driving the hips into the bar until your hips and knees are extended.']::text[],'piernas',ARRAY['biceps','gluteos','espalda']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean_Deadlift/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean_Deadlift/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean_Deadlift/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Clean Pull','clean-pull','Ejercicio de tirón, compuesto.',ARRAY['With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.','Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight and elbows out. Move the weight with control as you continue to above the knees.','Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended. Full extension should be violent and abrupt, and ensure that you do not prolong the extension for longer than necessary.']::text[],'piernas',ARRAY['biceps','gluteos','espalda']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean_Pull/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean_Pull/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean_Pull/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Clean from Blocks','clean-from-blocks','Ejercicio de tirón, compuesto.',ARRAY['With a barbell on boxes or stands of the desired height, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.','Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight with the elbows pointed out.','As full extension is achieved, transition into the receiving position by aggressively shrugging and flexing the arms with the elbows up and out. Aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.','Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position. Return the weight to the boxes for the next rep.']::text[],'piernas',ARRAY['gluteos','hombros','espalda']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean_from_Blocks/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean_from_Blocks/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean_from_Blocks/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Double Kettlebell Alternating Hang Clean','double-kettlebell-alternating-hang-clean','Ejercicio de tirón, compuesto.',ARRAY['Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.','Clean one kettlebell to your shoulder and hold on to the other kettlebell.','With a fluid motion, lower the top kettlebell while driving the bottom kettlebell up.']::text[],'piernas',ARRAY['biceps','gluteos','espalda']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Double_Kettlebell_Alternating_Hang_Clean/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Double_Kettlebell_Alternating_Hang_Clean/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Double_Kettlebell_Alternating_Hang_Clean/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Double Leg Butt Kick','double-leg-butt-kick','Ejercicio de empuje, compuesto.',ARRAY['Begin standing with your knees slightly bent.','Quickly squat a short distance, flexing the hips and knees, and immediately extend to jump for maximum vertical height.','As you go up, tuck your heels by flexing the knees, attempting to touch the buttocks.','Finish the motion by landing with the knees only partially bent, using your legs to absorb the impact.']::text[],'piernas',ARRAY['gluteos']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Double_Leg_Butt_Kick/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Double_Leg_Butt_Kick/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Double_Leg_Butt_Kick/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Dumbbell Clean','dumbbell-clean','Ejercicio de tirón, compuesto.',ARRAY['Begin standing with a dumbbell in each hand with your feet shoulder width apart.','Lower the weights to the floor by flexing at the hips and knees, pushing your hips back until the dumbbells reach the floor. This will be your starting position.','To initiate the movement, violently jump upward by extending the hips, knees, and ankles to acclerate the weights upward. Maintaining a neutral grip on the dumbbells, keep the arms straight until full extension is reached.','After full extension, rebend the hips and knees to receive the weight in a squat position. Allow the arms to bend, guiding the dumbbells to your shoulders.','Upon receiving the weight in the squat position, extend the hips and knees to finish in a standing position with the weights on your shoulders.']::text[],'piernas',ARRAY['biceps','gluteos','espalda','hombros']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Clean/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Clean/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Clean/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Dumbbell Lunges','dumbbell-lunges','Ejercicio de empuje, compuesto.',ARRAY['Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.','Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.','Using mainly the heel of your foot, push up and go back to the starting position as you exhale.','Repeat the movement for the recommended amount of repetitions and then perform with the left leg.']::text[],'piernas',ARRAY['gluteos']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lunges/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lunges/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lunges/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Dumbbell Rear Lunge','dumbbell-rear-lunge','Ejercicio de empuje, compuesto.',ARRAY['Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.','Step backward with your right leg around two feet or so from the left foot and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Tip: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground. Keep the torso upright during the lunge; flexible hip flexors are important. A long lunge emphasizes the Gluteus Maximus; a short lunge emphasizes Quadriceps.','Push up and go back to the starting position as you exhale. Tip: Use the ball of your feet to push in order to accentuate the quadriceps. To focus on the glutes, press with your heels.','Now repeat with the opposite leg.']::text[],'piernas',ARRAY['gluteos']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Rear_Lunge/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Rear_Lunge/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Rear_Lunge/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Dumbbell Seated Box Jump','dumbbell-seated-box-jump','Ejercicio de empuje, compuesto.',ARRAY['Position a box a couple feet to the side of a bench. Hold a dumbbell to your chest with both hands and seat yourself on the bench facing the box. This will be your starting position.','Plant your feet firmly on the ground as you lean forward, extending through the hips and knees to jump up and forward.','Land on the box with both feet, absorbing the impact by allowing the hips and knees to bend.','Step down and return to the starting position.']::text[],'piernas',ARRAY['gluteos']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Seated_Box_Jump/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Seated_Box_Jump/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Seated_Box_Jump/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Dumbbell Squat','dumbbell-squat','Ejercicio de empuje, compuesto.',ARRAY['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).','Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.','Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until your thighs are parallel to the floor. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise your torso as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'piernas',ARRAY['gluteos','espalda']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Squat/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Squat/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Squat/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Dumbbell Squat To A Bench','dumbbell-squat-to-a-bench','Ejercicio de empuje, compuesto.',ARRAY['Stand up straight with a flat bench behind you while holding a dumbbell on each hand (palms facing the side of your legs).','Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.','Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until you slightly touch the bench behind you. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'piernas',ARRAY['gluteos','espalda']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Squat_To_A_Bench/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Squat_To_A_Bench/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Squat_To_A_Bench/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Dumbbell Step Ups','dumbbell-step-ups','Ejercicio de empuje, compuesto.',ARRAY['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).','Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.','Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.','Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.']::text[],'piernas',ARRAY['gluteos']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Step_Ups/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Step_Ups/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Step_Ups/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Elevated Back Lunge','elevated-back-lunge','Ejercicio de empuje, compuesto.',ARRAY['Position a bar onto a rack at shoulder height loaded to an appropriate weight. Place a short, raised platform behind you.','Rack the bar onto your upper back, keeping your back arched and tight. Step onto your raised platform with both feet. This will be your starting position.','Begin by stepping backwards with one leg. Descend by flexing your hips and knees until your knee touches the floor.','Pause, and extend through the hips and knees to rise up, returning all the way to the starting position before alternating.']::text[],'piernas',ARRAY['gluteos']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Elevated_Back_Lunge/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Elevated_Back_Lunge/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Elevated_Back_Lunge/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Fast Skipping','fast-skipping','Ejercicio de empuje, compuesto.',ARRAY['Start in a relaxed position with one leg slightly forward. This will be your starting position.','Skip by executing a step-hop pattern of right-right-step to left-left-step, and so on, alternating back and forth.','Perform fast skips by maintaining close contact with the ground and reduce air time, moving as quickly as possible.']::text[],'piernas',ARRAY['gluteos']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Fast_Skipping/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Fast_Skipping/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Fast_Skipping/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Frankenstein Squat','frankenstein-squat','Ejercicio de empuje, compuesto.',ARRAY['This drill teaches you the proper positioning of both the bar and your body during the clean and front squat.','Place the barbell on the front of the shoulders, releasing your grip and extending your arms out in front of you. The shoulders should be pushed forward to create a shelf, and the bar should be in contact with the throat. Ensure that you only move your shoulder blades forward; don''t round the thoracic spine.','Squat by flexing the knees and hips, sitting in between your legs. Keep the torso upright, the arms up, and the shoulders forward, and the bar should stay in place. Go to the bottom of the squat, until your hamstrings contact your calves.','Return to the upright position by driving through the front of the heel and extending the knees and hips.']::text[],'piernas',ARRAY['abdomen','gluteos']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Frankenstein_Squat/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Frankenstein_Squat/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Frankenstein_Squat/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Freehand Jump Squat','freehand-jump-squat','Ejercicio de empuje, compuesto.',ARRAY['Cross your arms over your chest.','With your head up and your back straight, position your feet at shoulder width.','Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor.','Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement.','When you touch the floor again, immediately squat down and jump again.','Repeat for the recommended amount of repetitions.']::text[],'piernas',ARRAY['gluteos']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Freehand_Jump_Squat/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Freehand_Jump_Squat/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Freehand_Jump_Squat/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Front Squat (Clean Grip)','front-squat-clean-grip','Ejercicio de empuje, compuesto.',ARRAY['To begin, first set the bar in a rack slightly below shoulder level. Rest the bar on top of the deltoids, pushing into the clavicles, and lightly touching the throat. Your hands should be in a clean grip, touching the bar only with your fingers to help keep it in position.','Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head and elbows up at all times. This will be your starting position.','Bend at the knees, sitting down between your legs. Continue down until your hamstrings are on your calves. Keep your knees aligned with your feet by consciously using your abductors to push your knees out as you squat.','Begin to raise the bar as you exhale by pushing the floor mainly with the heel or middle of your foot as you straighten the legs again and return to the starting position.']::text[],'piernas',ARRAY['abdomen','gluteos']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Front_Squat_Clean_Grip/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Front_Squat_Clean_Grip/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Front_Squat_Clean_Grip/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Front Squats With Two Kettlebells','front-squats-with-two-kettlebells','Ejercicio de empuje, compuesto.',ARRAY['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.','Looking straight ahead at all times, squat as low as you can and pause at the bottom. As you squat down, push your knees out. You should squat between your legs, keeping an upright torso, with your head and chest up.','Rise back up by driving through your heels and repeat.']::text[],'piernas',ARRAY['gluteos']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Front_Squats_With_Two_Kettlebells/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Front_Squats_With_Two_Kettlebells/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Front_Squats_With_Two_Kettlebells/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Glute Ham Raise','glute-ham-raise','Ejercicio de tirón, compuesto.',ARRAY['Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad.','Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright.','Return to the starting position, keeping your descent under control.']::text[],'piernas',ARRAY['gluteos']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Glute_Ham_Raise/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Glute_Ham_Raise/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Glute_Ham_Raise/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Goblet Squat','goblet-squat','Ejercicio de empuje, compuesto.',ARRAY['Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.','Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.','At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions.']::text[],'piernas',ARRAY['gluteos','hombros']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Goblet_Squat/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Goblet_Squat/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Goblet_Squat/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Good Morning','good-morning','Ejercicio de empuje, compuesto.',ARRAY['Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.','Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.','Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position.']::text[],'piernas',ARRAY['abdomen','gluteos','espalda']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Good_Morning/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Good_Morning/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Good_Morning/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Good Morning off Pins','good-morning-off-pins','Ejercicio de empuje, compuesto.',ARRAY['Begin with a bar on a rack at about the same height as your stomach. Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.','Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight. Slowly lower the weight back to the pins returning to the starting position.']::text[],'piernas',ARRAY['abdomen','gluteos','espalda']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Good_Morning_off_Pins/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Good_Morning_off_Pins/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Good_Morning_off_Pins/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Barbell Deadlift','barbell-deadlift','Ejercicio de tirón, compuesto.',ARRAY['Stand in front of a loaded barbell.','While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.','While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.','Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.','Perform the amount of repetitions prescribed in the program.']::text[],'espalda',ARRAY['piernas','biceps','gluteos']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Deadlift/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Deadlift/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Deadlift/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Bent-Arm Barbell Pullover','bent-arm-barbell-pullover','Ejercicio de tirón, compuesto.',ARRAY['Lie on a flat bench with a barbell using a shoulder grip width.','Hold the bar straight over your chest with a bend in your arms. This will be your starting position.','While keeping your arms in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.','At that point, bring the barbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.','Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.']::text[],'espalda',ARRAY['pecho','hombros','triceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent-Arm_Barbell_Pullover/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent-Arm_Barbell_Pullover/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent-Arm_Barbell_Pullover/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Bent Over Barbell Row','bent-over-barbell-row','Ejercicio de tirón, compuesto.',ARRAY['Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.','Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.','Then inhale and slowly lower the barbell back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'espalda',ARRAY['biceps','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_Barbell_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_Barbell_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_Barbell_Row/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Bent Over One-Arm Long Bar Row','bent-over-one-arm-long-bar-row','Ejercicio de tirón, compuesto.',ARRAY['Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.','Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.','Now grab the bar with one arm just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.','Pull the bar straight up with your elbow in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Do not allow for any swinging of the torso. Only the arm should move.','Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).','Repeat for the recommended amount of repetitions and switch arms.']::text[],'espalda',ARRAY['biceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_One-Arm_Long_Bar_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_One-Arm_Long_Bar_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_One-Arm_Long_Bar_Row/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Bent Over Two-Arm Long Bar Row','bent-over-two-arm-long-bar-row','Ejercicio de tirón, compuesto.',ARRAY['Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.','Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.','Now grab the bar with both arms just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.','Pull the bar straight up with your elbows in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Use a stirrup or double handle cable attachment by hooking it under the end of the bar.','Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).','Repeat for the recommended amount of repetitions.']::text[],'espalda',ARRAY['biceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_Two-Arm_Long_Bar_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_Two-Arm_Long_Bar_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_Two-Arm_Long_Bar_Row/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Bent Over Two-Dumbbell Row','bent-over-two-dumbbell-row','Ejercicio de tirón, compuesto.',ARRAY['With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.','While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), keeping the elbows close to the body (do not exert any force with the forearm other than holding the weights). On the top contracted position, squeeze the back muscles and hold for a second.','Slowly lower the weight again to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'espalda',ARRAY['biceps','hombros']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_Two-Dumbbell_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_Two-Dumbbell_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_Two-Dumbbell_Row/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Bent Over Two-Dumbbell Row With Palms In','bent-over-two-dumbbell-row-with-palms-in','Ejercicio de tirón, compuesto.',ARRAY['With a dumbbell in each hand (palms facing each other), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.','While keeping the torso stationary, lift the dumbbells to your side as you breathe out, squeezing your shoulder blades together. On the top contracted position, squeeze the back muscles and hold for a second.','Slowly lower the weight again to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'espalda',ARRAY['biceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_Two-Dumbbell_Row_With_Palms_In/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_Two-Dumbbell_Row_With_Palms_In/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_Two-Dumbbell_Row_With_Palms_In/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Chin-Up','chin-up','Ejercicio de tirón, compuesto.',ARRAY['Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.','As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.','As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.','After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.','Repeat this motion for the prescribed amount of repetitions.']::text[],'espalda',ARRAY['biceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chin-Up/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chin-Up/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chin-Up/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Clean Shrug','clean-shrug','Ejercicio de tirón, compuesto.',ARRAY['Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.','Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a clean, avoid overloading to the point that the execution slows down.']::text[],'espalda',ARRAY['biceps','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean_Shrug/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean_Shrug/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean_Shrug/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Close-Grip Front Lat Pulldown','close-grip-front-lat-pulldown','Ejercicio de tirón, compuesto.',ARRAY['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.','Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.','As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.','As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.','After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.','6. Repeat this motion for the prescribed amount of repetitions.']::text[],'espalda',ARRAY['biceps','hombros']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_Front_Lat_Pulldown/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_Front_Lat_Pulldown/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_Front_Lat_Pulldown/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Deficit Deadlift','deficit-deadlift','Ejercicio de tirón, compuesto.',ARRAY['Begin by having a platform or weight plates that you can stand on, usually 1-3 inches in height. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.','With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.','Lower the bar by bending at the hips and guiding it to the floor.']::text[],'espalda',ARRAY['biceps','gluteos','piernas']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Deficit_Deadlift/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Deficit_Deadlift/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Deficit_Deadlift/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Dumbbell Incline Row','dumbbell-incline-row','Ejercicio de tirón, compuesto.',ARRAY['Using a neutral grip, lean into an incline bench.','Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.','Retract the shoulder blades and flex the elbows to row the dumbbells to your side.','Pause at the top of the motion, and then return to the starting position.']::text[],'espalda',ARRAY['biceps','hombros']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Incline_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Incline_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Incline_Row/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Elevated Cable Rows','elevated-cable-rows','Ejercicio de tirón, compuesto.',ARRAY['Get a platform of some sort (it can be an aerobics or calf raise platform) that is around 4-6 inches in height.','Place it on the seat of the cable row machine.','Sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.','Lean over as you keep the natural alignment of your back and grab the V-bar handles.','With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.','Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.','Repeat for the recommended amount of repetitions.']::text[],'espalda',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Elevated_Cable_Rows/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Elevated_Cable_Rows/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Elevated_Cable_Rows/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Full Range-Of-Motion Lat Pulldown','full-range-of-motion-lat-pulldown','Ejercicio de tirón, compuesto.',ARRAY['Either standing or seated on a high bench, grasp two stirrup cables that are attached to the high pulleys. Grab with the opposing hand so your arms are crisscrossed about you and your palms are facing forward.','Keeping your chest up and maintaining a slight arch in your lower back, pull the handles down as if you were doing a regular pulldown. The range of motion will be more of an arc. During the movement, rotate your hands so that in the bottom position your palms face each other rather than forward. Return slowly to the starting position and repeat.']::text[],'espalda',ARRAY['biceps','hombros']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Full_Range-Of-Motion_Lat_Pulldown/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Full_Range-Of-Motion_Lat_Pulldown/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Full_Range-Of-Motion_Lat_Pulldown/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Hyperextensions With No Hyperextension Bench','hyperextensions-with-no-hyperextension-bench','Ejercicio de tirón, compuesto.',ARRAY['With someone holding down your legs, slide yourself down to the edge a flat bench until your hips hang off the end of the bench. Tip: Your entire upper body should be hanging down towards the floor. Also, you will be in the same position as if you were on a hyperextension bench but the range of motion will be shorter due to the height of the flat bench vs. that of the hyperextension bench.','With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.','Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you almost touch the floor or you feel a nice stretch on the hamstrings (whichever comes first). Tip: Never round the back as you perform this exercise.','Slowly raise your torso back to the initial position as you exhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.','Repeat for the recommended amount of repetitions.']::text[],'espalda',ARRAY['gluteos','piernas']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hyperextensions_With_No_Hyperextension_Bench/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hyperextensions_With_No_Hyperextension_Bench/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hyperextensions_With_No_Hyperextension_Bench/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Kettlebell Sumo High Pull','kettlebell-sumo-high-pull','Ejercicio de tirón, compuesto.',ARRAY['Place a kettlebell on the ground between your feet. Position your feet in a wide stance, and grasp the kettlebell with two hands. Set your hips back as far as possible, with your knees bent. Keep your chest and head up. This will be your starting position.','Begin by extending the hips and knees, simultaneously pulling the kettlebell to your shoulders, raising your elbows as you do so. Reverse the motion to return to the starting position.']::text[],'espalda',ARRAY['piernas','gluteos','hombros']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Sumo_High_Pull/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Sumo_High_Pull/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Sumo_High_Pull/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Kneeling High Pulley Row','kneeling-high-pulley-row','Ejercicio de tirón, compuesto.',ARRAY['Select the appropriate weight using a pulley that is above your head. Attach a rope to the cable and kneel a couple of feet away, holding the rope out in front of you with both arms extended. This will be your starting position.','Initiate the movement by flexing the elbows and fully retracting your shoulders, pulling the rope toward your upper chest with your elbows out.','After pausing briefly, slowly return to the starting position.']::text[],'espalda',ARRAY['biceps']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_High_Pulley_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_High_Pulley_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_High_Pulley_Row/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Kneeling Single-Arm High Pulley Row','kneeling-single-arm-high-pulley-row','Ejercicio de tirón, compuesto.',ARRAY['Attach a single handle to a high pulley and make your weight selection.','Kneel in front of the cable tower, taking the cable with one hand with your arm extended. This will be your starting position.','Starting with your palm facing forward, pull the weight down to your torso by flexing the elbow and retract the shoulder blade. As you do so, rotate the wrist so that at the completion of the movement, your palm is now facing you.','After a brief pause, return to the starting position.']::text[],'espalda',ARRAY['biceps']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_Single-Arm_High_Pulley_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_Single-Arm_High_Pulley_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_Single-Arm_High_Pulley_Row/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Leverage High Row','leverage-high-row','Ejercicio de tirón, compuesto.',ARRAY['Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the knee pad to help keep you down. Grasp the handles with a pronated grip. This will be your starting position.','Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.','Pause at the bottom of the motion, and then slowly return the handles to the starting position.','For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked.']::text[],'espalda',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leverage_High_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leverage_High_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leverage_High_Row/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Leverage Iso Row','leverage-iso-row','Ejercicio de tirón, compuesto.',ARRAY['Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position.','Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.','Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked.']::text[],'espalda',ARRAY['biceps']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leverage_Iso_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leverage_Iso_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leverage_Iso_Row/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Lying T-Bar Row','lying-t-bar-row','Ejercicio de tirón, compuesto.',ARRAY['Load up the T-bar Row Machine with the desired weight and adjust the leg height so that your upper chest is at the top of the pad. Tip: In some machines all you can do is stand on the appropriate step that allows you to be at a height that has the upper chest at the top of the pad.','Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part of your back you want to emphasize.','Lift the bar off the rack and extend your arms in front of you. This will be your starting position.','As you exhale slowly pull the weight up and squeeze your back at the top of the movement. Tip: Keep the upper arms as close to the torso as possible throughout the movement in order to better engage the back muscles. Also, do not lift your body off of the pad at any time and refrain from using the biceps to lift the weight.','After a second contraction at the top of the movement, as you inhale, slowly go back down to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'espalda',ARRAY['biceps']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_T-Bar_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_T-Bar_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_T-Bar_Row/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('One-Arm Dumbbell Row','one-arm-dumbbell-row','Ejercicio de tirón, compuesto.',ARRAY['Choose a flat bench and place a dumbbell on each side of it.','Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.','Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.','Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.','Lower the resistance straight down to the starting position. Breathe in as you perform this step.','Repeat the movement for the specified amount of repetitions.','Switch sides and repeat again with the other arm.']::text[],'espalda',ARRAY['biceps','hombros']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Arm_Dumbbell_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Arm_Dumbbell_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Arm_Dumbbell_Row/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('One-Arm Kettlebell Row','one-arm-kettlebell-row','Ejercicio de tirón, compuesto.',ARRAY['Place a kettlebell in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position. Grab the kettlebell and pull it to your stomach, retracting your shoulder blade and flexing the elbow. Keep your back straight. Lower and repeat.']::text[],'espalda',ARRAY['biceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Arm_Kettlebell_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Arm_Kettlebell_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Arm_Kettlebell_Row/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('One-Arm Long Bar Row','one-arm-long-bar-row','Ejercicio de tirón, compuesto.',ARRAY['Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.','Stand next to the bar, and take a grip with one hand close to the collar. Using your hips and legs, rise to a standing position.','Assume a bent-knee stance with your hips back and your chest up. Your arm should be extended. This will be your starting position.','Pull the weight to your side by retracting the shoulder and flexing the elbow. Do not jerk the weight or cheat during the movement.','After a brief pause, return to the starting position.']::text[],'espalda',ARRAY['biceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Arm_Long_Bar_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Arm_Long_Bar_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Arm_Long_Bar_Row/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('One Arm Lat Pulldown','one-arm-lat-pulldown','Ejercicio de tirón, compuesto.',ARRAY['Select an appropriate weight and adjust the knee pad to help keep you down. Grasp the handle with a pronated grip. This will be your starting position.','Pull the handle down, squeezing your elbow to your side as you flex the elbow.','Pause at the bottom of the motion, and then slowly return the handle to the starting position.','For multiple repetitions, avoid completely returning the weight to keep tension on the muscles being worked.']::text[],'espalda',ARRAY['biceps']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One_Arm_Lat_Pulldown/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One_Arm_Lat_Pulldown/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One_Arm_Lat_Pulldown/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Pullups','pullups','Ejercicio de tirón, compuesto.',ARRAY['Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.','As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.','Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.','After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.','Repeat this motion for the prescribed amount of repetitions.']::text[],'espalda',ARRAY['biceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Pullups/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Pullups/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Pullups/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Rack Pull with Bands','rack-pull-with-bands','Ejercicio de tirón, compuesto.',ARRAY['Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Attach bands to the base of the rack, or secure them with dumbbells. Attach the other end to the bar. You may need to choke the bands to provide tension.','Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight.','With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement. Return the weight to the pins and repeat.']::text[],'espalda',ARRAY['biceps','gluteos','piernas']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Rack_Pull_with_Bands/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Rack_Pull_with_Bands/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Rack_Pull_with_Bands/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Rack Pulls','rack-pulls','Ejercicio de tirón, compuesto.',ARRAY['Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight.','With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement.','Return the weight to the pins and repeat.']::text[],'espalda',ARRAY['biceps','gluteos','piernas']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Rack_Pulls/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Rack_Pulls/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Rack_Pulls/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Reverse Grip Bent-Over Rows','reverse-grip-bent-over-rows','Ejercicio de tirón, compuesto.',ARRAY['Stand erect while holding a barbell with a supinated grip (palms facing up).','Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.','While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.','Slowly lower the weight again to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'espalda',ARRAY['biceps','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Reverse_Grip_Bent-Over_Rows/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Reverse_Grip_Bent-Over_Rows/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Reverse_Grip_Bent-Over_Rows/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Seated Cable Rows','seated-cable-rows','Ejercicio de tirón, compuesto.',ARRAY['For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.','Lean over as you keep the natural alignment of your back and grab the V-bar handles.','With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.','Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.','Repeat for the recommended amount of repetitions.']::text[],'espalda',ARRAY['biceps','hombros']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Seated_Cable_Rows/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Seated_Cable_Rows/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Seated_Cable_Rows/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Seated Good Mornings','seated-good-mornings','Ejercicio de tirón, compuesto.',ARRAY['Set up a box in a power rack. The pins should be set at an appropriate height. Begin by stepping under the bar and placing it across the back of the shoulders, not on top of your traps. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders.','Remove the bar from the rack, creating a tight arch in your lower back. Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. This will be your starting position.','Keeping the bar tight, bend forward at the hips as much as possible. If you set the pins to what would be parallel, you not only have a safety if you fail, but know when to stop.','Pause just above the pins and reverse the motion until your torso it upright.']::text[],'espalda',ARRAY['gluteos']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Seated_Good_Mornings/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Seated_Good_Mornings/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Seated_Good_Mornings/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Seated One-arm Cable Pulley Rows','seated-one-arm-cable-pulley-rows','Ejercicio de tirón, compuesto.',ARRAY['To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.','Lean over as you keep the natural alignment of your back and grab the single handle attachment with your left arm using a palms-down grip.','With your arm extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lat as you hold the bar in front of you. The right arm can be kept by the waist. This is the starting position of the exercise.','Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it as you rotate the wrist, so that by the time your hand is by your abdominals it is in a neutral position (palms facing the torso). Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard.','Hold that contraction for a second and slowly go back to the original position while breathing in. Tip: Remember to rotate the wrist as you go back to the starting position so that the palms are facing down again.','Repeat for the recommended amount of repetitions and then perform the same movement with the right hand.']::text[],'espalda',ARRAY['biceps']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Seated_One-arm_Cable_Pulley_Rows/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Seated_One-arm_Cable_Pulley_Rows/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Seated_One-arm_Cable_Pulley_Rows/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Shotgun Row','shotgun-row','Ejercicio de tirón, compuesto.',ARRAY['Attach a single handle to a low cable.','After selecting the correct weight, stand a couple feet back with a wide-split stance. Your arm should be extended and your shoulder forward. This will be your starting position.','Perform the movement by retracting the shoulder and flexing the elbow. As you pull, supinate the wrist, turning the palm upward as you go.','After a brief pause, return to the starting position.']::text[],'espalda',ARRAY['biceps']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Shotgun_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Shotgun_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Shotgun_Row/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Smith Machine Bent Over Row','smith-machine-bent-over-row','Ejercicio de tirón, compuesto.',ARRAY['Set the barbell attached to the smith machine to a height that is about 2 inches below your knees.','Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up.','Now grasp the barbell using an overhand (pronated) grip and unlock it from the smith machine rack. Then let it hang directly in front of you as your arms hang extended perpendicular to the floor and your torso. This is your starting position.','While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.','Slowly lower the weight again to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'espalda',ARRAY['biceps','hombros']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Smith_Machine_Bent_Over_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Smith_Machine_Bent_Over_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Smith_Machine_Bent_Over_Row/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Smith Machine Upright Row','smith-machine-upright-row','Ejercicio de tirón, compuesto.',ARRAY['To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.','Lift the barbell up and fully extend your arms with your back straight. There should be a slight bend at the elbows. This is the starting position.','Use your side shoulders to lift the bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the bar, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.','Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.','Repeat for the recommended amount of repetitions.']::text[],'espalda',ARRAY['biceps','hombros']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Smith_Machine_Upright_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Smith_Machine_Upright_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Smith_Machine_Upright_Row/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Snatch Shrug','snatch-shrug','Ejercicio de tirón, compuesto.',ARRAY['Begin with a wide grip, with the bar hanging at the mid thigh position. You can use a hook or overhand grip. Your back should be straight and inclined slightly forward.','Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a snatch, avoid overloading to the point that the execution slows down.']::text[],'espalda',ARRAY['biceps','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Snatch_Shrug/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Snatch_Shrug/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Snatch_Shrug/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Standing Dumbbell Upright Row','standing-dumbbell-upright-row','Ejercicio de tirón, compuesto.',ARRAY['Grasp a dumbbell in each hand with a pronated (palms forward) grip that is slightly less than shoulder width. The dumbbells should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.','Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be close to the body as you move it up and the elbows should drive the motion. Continue to lift them until they nearly touch your chin. Tip: Your elbows should drive the motion. As you lift the dumbbells, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.','Lower the dumbbells back down slowly to the starting position. Inhale as you perform this portion of the movement.','Repeat for the recommended amount of repetitions.']::text[],'espalda',ARRAY['biceps','hombros']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Standing_Dumbbell_Upright_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Standing_Dumbbell_Upright_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Standing_Dumbbell_Upright_Row/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Stiff Leg Barbell Good Morning','stiff-leg-barbell-good-morning','Ejercicio de empuje, compuesto.',ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a shoulder width medium stance. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position.','Keeping your legs stationary, move your torso forward by bending at the hips while inhaling. Lower your torso until it is parallel with the floor.','Begin to raise the bar as you exhale by elevating your torso back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'espalda',ARRAY['gluteos','piernas']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Stiff_Leg_Barbell_Good_Morning/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Stiff_Leg_Barbell_Good_Morning/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Stiff_Leg_Barbell_Good_Morning/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Bench Dips','bench-dips','Ejercicio de empuje, compuesto.',ARRAY['For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.','Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.','Using your triceps to bring your torso up again, lift yourself back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY['pecho','hombros']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Dips/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Dips/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Dips/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Bench Press - Powerlifting','bench-press-powerlifting','Ejercicio de empuje, compuesto.',ARRAY['Begin by lying on the bench, getting your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.','However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart.','Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.','Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[],'triceps',ARRAY['pecho','biceps','espalda','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Press_-_Powerlifting/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Press_-_Powerlifting/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Press_-_Powerlifting/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Board Press','board-press','Ejercicio de empuje, compuesto.',ARRAY['Begin by lying on the bench, getting your head beyond the bar if possible. One to five boards, made out of 2x6''s, can be screwed together and held in place by a training partner, bands, or just tucked under your shirt.','Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.','You can take a standard bench grip, or shoulder width to focus on the triceps. Pull the bar out of the rack without protracting your shoulders. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.','Lower the bar to the boards, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[],'triceps',ARRAY['pecho','biceps','espalda','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Board_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Board_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Board_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Close-Grip Barbell Bench Press','close-grip-barbell-bench-press','Ejercicio de empuje, compuesto.',ARRAY['Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[],'triceps',ARRAY['pecho','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_Barbell_Bench_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_Barbell_Bench_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_Barbell_Bench_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Close-Grip Dumbbell Press','close-grip-dumbbell-press','Ejercicio de empuje, compuesto.',ARRAY['Place a dumbbell standing up on a flat bench.','Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench with only your shoulders lying on the surface. Hips should be below the bench and your legs bent with your feet firmly on the floor.','Grasp the dumbbell with both hands and hold it straight over your chest at arm''s length. Both palms should be pressing against the underside of the sides of the dumbbell. This will be your starting position.','Initiate the movement by lowering the dumbbell to your chest.','Return to the starting position by extending the elbows.']::text[],'triceps',ARRAY['pecho','hombros']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_Dumbbell_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_Dumbbell_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_Dumbbell_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Close-Grip EZ-Bar Press','close-grip-ez-bar-press','Ejercicio de empuje, compuesto.',ARRAY['Lie on a flat bench with an EZ bar loaded to an appropriate weight.','Using a narrow grip lift the bar and hold it straight over your torso with your elbows in. The arms should be perpendicular to the floor. This will be your starting position.','Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.','Using the triceps to push the bar back up, press it back to the starting position by extending the elbows as you exhale.','Repeat.']::text[],'triceps',ARRAY['pecho','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_EZ-Bar_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_EZ-Bar_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_EZ-Bar_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Close-Grip Push-Up off of a Dumbbell','close-grip-push-up-off-of-a-dumbbell','Ejercicio de empuje, compuesto.',ARRAY['Lie on the floor and place your hands on an upright dumbbell. Supporting your weight on your toes and hands, keep your torso rigid and your elbows in with your arms straight. This will be your starting position.','Lower your body, allowing the elbows to flex while you inhale. Keep your body straight, not allowing your hips to rise or sag.','Press yourself back up to the starting position by extending the elbows. Breathe out as you perform this step.','After a pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[],'triceps',ARRAY['abdomen','pecho','hombros']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_Push-Up_off_of_a_Dumbbell/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_Push-Up_off_of_a_Dumbbell/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_Push-Up_off_of_a_Dumbbell/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Decline Close-Grip Bench To Skull Crusher','decline-close-grip-bench-to-skull-crusher','Ejercicio de empuje, compuesto.',ARRAY['Secure your legs at the end of the decline bench and slowly lay down on the bench.','Using a close grip (a grip that is slightly less than shoulder width), lift the bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.','Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.','Using the triceps to push the bar back up, press it back to the starting position as you exhale.','As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.','Lift the bar back to the starting position by contracting the triceps and exhaling.','Repeat steps 3-6 until the recommended amount of repetitions is performed.']::text[],'triceps',ARRAY['pecho','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Close-Grip_Bench_To_Skull_Crusher/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Close-Grip_Bench_To_Skull_Crusher/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Close-Grip_Bench_To_Skull_Crusher/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Dip Machine','dip-machine','Ejercicio de empuje, compuesto.',ARRAY['Sit securely in a dip machine, select the weight and firmly grasp the handles.','Now keep your elbows in at your sides in order to place emphasis on the triceps. The elbows should be bent at a 90 degree angle.','As you contract the triceps, extend your arms downwards as you exhale. Tip: At the bottom of the movement, focus on keeping a little bend in your arms to keep tension on the triceps muscle.','Now slowly let your arms come back up to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY['pecho','hombros']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dip_Machine/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dip_Machine/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dip_Machine/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Dips - Triceps Version','dips-triceps-version','Ejercicio de empuje, compuesto.',ARRAY['To get into the starting position, hold your body at arm''s length with your arms nearly locked above the bars.','Now, inhale and slowly lower yourself downward. Your torso should remain upright and your elbows should stay close to your body. This helps to better focus on tricep involvement. Lower yourself until there is a 90 degree angle formed between the upper arm and forearm.','Then, exhale and push your torso back up using your triceps to bring your body back to the starting position.','Repeat the movement for the prescribed amount of repetitions.']::text[],'triceps',ARRAY['pecho','hombros']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dips_-_Triceps_Version/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dips_-_Triceps_Version/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dips_-_Triceps_Version/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Dumbbell Floor Press','dumbbell-floor-press','Ejercicio de empuje, compuesto.',ARRAY['Lay on the floor holding dumbbells in your hands. Your knees can be bent. Begin with the weights fully extended above you.','Lower the weights until your upper arm comes in contact with the floor. You can tuck your elbows to emphasize triceps size and strength, or to focus on your chest angle your arms to the side.','Pause at the bottom, and then bring the weight together at the top by extending through the elbows.']::text[],'triceps',ARRAY['pecho','hombros']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Floor_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Floor_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Floor_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Floor Press','floor-press','Ejercicio de empuje, compuesto.',ARRAY['Adjust the j-hooks so they are at the appropriate height to rack the bar. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together; pull the bar off of the hooks.','Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.','Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so.']::text[],'triceps',ARRAY['pecho','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Floor_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Floor_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Floor_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Floor Press with Chains','floor-press-with-chains','Ejercicio de empuje, compuesto.',ARRAY['Adjust the j-hooks so they are at the appropriate height to rack the bar. For this exercise, drape the chains directly over the end of the bar, trying to keep the ends away from the plates.','Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together, pull the bar off of the hooks.','Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.','Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so.']::text[],'triceps',ARRAY['pecho','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Floor_Press_with_Chains/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Floor_Press_with_Chains/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Floor_Press_with_Chains/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Incline Push-Up Close-Grip','incline-push-up-close-grip','Ejercicio de empuje, compuesto.',ARRAY['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.','Place your hands next to one another on the bar.','Position your feet back from the bar with arms and body straight. This will be your starting position.','Keeping your body straight, lower your chest to the bar by bending the arms.','Return to the starting position by extending the elbows, pressing yourself back up.']::text[],'triceps',ARRAY['pecho','hombros']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Push-Up_Close-Grip/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Push-Up_Close-Grip/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Push-Up_Close-Grip/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('JM Press','jm-press','Ejercicio de empuje, compuesto.',ARRAY['Start the exercise the same way you would a close grip bench press. You will lie on a flat bench while holding a barbell at arms length (fully extended) with the elbows in. However, instead of having the arms perpendicular to the torso, make sure the bar is set in a direct line above the upper chest. This will be your starting position.','Now beginning from a fully extended position lower the bar down as if performing a lying triceps extension. Inhale as you perform this movement. When you reach the half way point, let the bar roll back about one inch by moving the upper arms towards your legs until they are perpendicular to the torso. Tip: Keep the bend at the elbows constant as you bring the upper arms forward.','As you exhale, press the bar back up by using the triceps to perform a close grip bench press.','Now go back to the starting position and start over.','Repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY['pecho','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/JM_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/JM_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/JM_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('One Arm Floor Press','one-arm-floor-press','Ejercicio de empuje, compuesto.',ARRAY['Lie down on a flat surface with your back pressing against the floor or an exercise mat. Make sure your knees are bent.','Have a partner hand you the bar on one hand. When starting, your arm should be just about fully extended, similar to the starting position of a barbell bench press. However, this time your grip will be neutral (palms facing your torso).','Make sure the hand you are not using to lift the weight is placed by your side.','Begin the exercise by lowering the barbell until your elbow touches the ground. Make sure to breathe in as this is the eccentric (lowering part of the exercise).','Then start lifting the barbell back up to the original starting position. Remember to breathe out during the concentric (lifting part of the exercise).','Repeat until you have performed your recommended repetitions.','Switch arms and repeat the movement.']::text[],'triceps',ARRAY['pecho','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One_Arm_Floor_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One_Arm_Floor_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One_Arm_Floor_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Pin Presses','pin-presses','Ejercicio de empuje, compuesto.',ARRAY['Pin presses remove the eccentric phase of the bench press, developing starting strength. They also allow you to train a desired range of motion.','The bench should be set up in a power rack. Set the pins to the desired point in your range of motion, whether it just be lockout or an inch off of your chest. The bar should be moved to the pins and prepared for lifting.','Begin by lying on the bench, with the bar directly above the contact point during your regular bench. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.','You can take a standard bench grip, or shoulder width to focus on the triceps. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.','Drive the bar up with as much force as possible. The elbows should be tucked in until lockout.','Return the bar to the pins, pausing before beginning the next repetition.']::text[],'triceps',ARRAY['pecho','biceps','espalda','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Pin_Presses/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Pin_Presses/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Pin_Presses/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Push-Ups - Close Triceps Position','push-ups-close-triceps-position','Ejercicio de empuje, compuesto.',ARRAY['Lie on the floor face down and place your hands closer than shoulder width for a close hand position. Make sure that you are holding your torso up at arms'' length.','Lower yourself until your chest almost touches the floor as you inhale.','Using your triceps and some of your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.','After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[],'triceps',ARRAY['pecho','hombros']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Push-Ups_-_Close_Triceps_Position/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Push-Ups_-_Close_Triceps_Position/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Push-Ups_-_Close_Triceps_Position/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Reverse Band Bench Press','reverse-band-bench-press','Ejercicio de empuje, compuesto.',ARRAY['Position a bench inside a power rack, with the bar set to the correct height. Begin by anchoring bands either to band pegs or to the top of the rack. Ensure that you will be position properly under the bands. Attach the other end to the barbell.','Lie on the bench, tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar.','Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.','Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[],'triceps',ARRAY['pecho','biceps','espalda','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Reverse_Band_Bench_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Reverse_Band_Bench_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Reverse_Band_Bench_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Reverse Triceps Bench Press','reverse-triceps-bench-press','Ejercicio de empuje, compuesto.',ARRAY['Lie back on a flat bench. Using a close, supinated grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked extended in front of you and perpendicular to the floor. This will be your starting position.','As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[],'triceps',ARRAY['pecho','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Reverse_Triceps_Bench_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Reverse_Triceps_Bench_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Reverse_Triceps_Bench_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Smith Machine Close-Grip Bench Press','smith-machine-close-grip-bench-press','Ejercicio de empuje, compuesto.',ARRAY['Place a flat bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a close and pronated grip (palms facing forward) that is around shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.','When you are done, lock the bar back in the rack.']::text[],'triceps',ARRAY['pecho','hombros']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Smith_Machine_Close-Grip_Bench_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Smith_Machine_Close-Grip_Bench_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Smith_Machine_Close-Grip_Bench_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Band Skull Crusher','band-skull-crusher','Ejercicio de empuje, aislamiento.',ARRAY['Secure a band to the base of a rack or the bench. Lay on the bench so that the band is lined up with your head.','Take hold of the band, raising your elbows so that the upper arm is perpendicular to the floor. With the elbow flexed, the band should be above your head. This will be your starting position.','Extend through the elbow to straighten your arm, keeping your upper arm in place. Pause at the top of the motion, and return to the starting position.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['bandas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Skull_Crusher/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Skull_Crusher/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Skull_Crusher/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Bench Press with Chains','bench-press-with-chains','Ejercicio de empuje, compuesto.',ARRAY['Adjust the leader chain, shortening it to the desired length.Place the chains on the sleeves of the bar.','Lying on the bench, get your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar.','Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.','Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[],'triceps',ARRAY['pecho','espalda','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Press_with_Chains/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Press_with_Chains/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Press_with_Chains/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Body-Up','body-up','Ejercicio de empuje, aislamiento.',ARRAY['Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position.','Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground. Keep your torso rigid as you perform the movement.','Slowly lower your forearms back to the ground by allowing the elbows to flex.','Repeat.']::text[],'triceps',ARRAY['abdomen','biceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Body-Up/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Body-Up/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Body-Up/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Body Tricep Press','body-tricep-press','Ejercicio de empuje, aislamiento.',ARRAY['Position a bar in a rack at chest height.','Standing, take a shoulder width grip on the bar and step a yard or two back, feet together and arms extended so that you are leaning on the bar. This will be your starting position.','Begin by flexing the elbow, lowering yourself towards the bar.','Pause, and then reverse the motion by extending the elbows.','Progress from bodyweight by adding chains over your shoulders.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Body_Tricep_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Body_Tricep_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Body_Tricep_Press/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cable Incline Triceps Extension','cable-incline-triceps-extension','Ejercicio de empuje, aislamiento.',ARRAY['Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.','Grasp the straight bar attachment overhead with a pronated (overhand; palms down) narrow grip (less than shoulder width) and keep your elbows tucked in to your sides. Your upper arms should create around a 25 degree angle when measured from the floor.','Keeping the upper arms stationary, extend the arms as you flex the triceps. Breathe out during this portion of the movement and hold the contraction for a second.','Slowly go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Incline_Triceps_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Incline_Triceps_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Incline_Triceps_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cable Lying Triceps Extension','cable-lying-triceps-extension','Ejercicio de empuje, aislamiento.',ARRAY['Lie on a flat bench and grasp the straight bar attachment of a low pulley with a narrow overhand grip. Tip: The easiest way to do this is to have someone hand you the bar as you lay down.','With your arms extended, position the bar over your torso. Your arms and your torso should create a 90-degree angle. This will be your starting position.','Lower the bar by bending at the elbow while keeping the upper arms stationary and elbows in. Go down until the bar lightly touches your forehead. Breathe in as you perform this portion of the movement.','Flex the triceps as you lift the bar back to its starting position. Exhale as you perform this portion of the movement.','Hold for a second at the contracted position and repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Lying_Triceps_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Lying_Triceps_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Lying_Triceps_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cable One Arm Tricep Extension','cable-one-arm-tricep-extension','Ejercicio de empuje, aislamiento.',ARRAY['With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the weight stack.','Now pull the handle down so that your upper arm and elbow are locked in to the side of your body. Your upper arm and forearm should form an acute angle (less than 90-degrees). You can keep the other arm by the waist and you can have one leg in front of you and the other one back for better balance. This will be your starting position.','As you contract the triceps, move the single handle attachment down to your side until your arm is straight. Breathe out as you perform this movement. Tip: Only the forearms should move. Your upper arms should remain stationary at all times.','Squeeze the triceps and hold for a second in this contracted position.','Slowly return the handle to the starting position.','Repeat for the recommended amount of repetitions and then perform the same movement with the other arm.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_One_Arm_Tricep_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_One_Arm_Tricep_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_One_Arm_Tricep_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cable Rope Overhead Triceps Extension','cable-rope-overhead-triceps-extension','Ejercicio de empuje, aislamiento.',ARRAY['Attach a rope to the bottom pulley of the pulley machine.','Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.','Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.','Return to the starting position by flexing your triceps as you breathe out.','Repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Rope_Overhead_Triceps_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Rope_Overhead_Triceps_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Rope_Overhead_Triceps_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Decline Dumbbell Triceps Extension','decline-dumbbell-triceps-extension','Ejercicio de empuje, aislamiento.',ARRAY['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.','Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.','As you breathe in and you keep the upper arms stationary (and elbows in), bring the dumbbells down slowly by moving your forearms in a semicircular motion towards you until your thumbs are next to your ears. Breathe in as you perform this portion of the movement.','Lift the dumbbells back to the starting position by contracting the triceps and exhaling.','Repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Dumbbell_Triceps_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Dumbbell_Triceps_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Dumbbell_Triceps_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Decline EZ Bar Triceps Extension','decline-ez-bar-triceps-extension','Ejercicio de empuje, aislamiento.',ARRAY['Secure your legs at the end of the decline bench and slowly lay down on the bench.','Using a close grip (a grip that is slightly less than shoulder width), lift the EZ bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.','As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.','Lift the bar back to the starting position by contracting the triceps and exhaling.','Repeat until the recommended amount of repetitions is performed.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_EZ_Bar_Triceps_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_EZ_Bar_Triceps_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_EZ_Bar_Triceps_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Dumbbell One-Arm Triceps Extension','dumbbell-one-arm-triceps-extension','Ejercicio de empuje, aislamiento.',ARRAY['Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.','Clean the dumbbell up to bring it to shoulder height and then extend the arm over your head so that the whole arm is perpendicular to the floor and next to your head. The dumbbell should be on top of you. The other hand can be kept fully extended to the side, by the waist, supporting the upper arm that has the dumbbell or grabbing a fixed surface.','Rotate the wrist so that the palm of your hand is facing forward and the pinkie is facing the ceiling. This will be your starting position.','Slowly lower the dumbbell behind your head as you hold the upper arm stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.','Return to the starting position by flexing your triceps as you breathe out. Tip: It is imperative that only the forearm moves. The upper arm should remain at all times stationary next to your head.','Repeat for the recommended amount of repetitions and switch arms.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_One-Arm_Triceps_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_One-Arm_Triceps_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_One-Arm_Triceps_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Dumbbell Tricep Extension -Pronated Grip','dumbbell-tricep-extension-pronated-grip','Ejercicio de empuje, aislamiento.',ARRAY['Lie down on a flat bench holding two dumbbells directly above your shoulders. Your arms should be fully extended and form a 90 degree angle from your torso and the floor.','The palms of your hands should be facing forward, and your elbows should be tucked in. This will be your starting position.','Now, inhale and slowly lower the dumbbells until they are near your ears. Be sure to keep your upper arms stationary and your elbows tucked in.','Then, exhale and use your triceps to return the weight to the starting position.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Tricep_Extension_-Pronated_Grip/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Tricep_Extension_-Pronated_Grip/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Tricep_Extension_-Pronated_Grip/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('EZ-Bar Skullcrusher','ez-bar-skullcrusher','Ejercicio de empuje, aislamiento.',ARRAY['Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.','Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.','Lift the bar back to the starting position by extending the elbow and exhaling.','Repeat.']::text[],'triceps',ARRAY['biceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/EZ-Bar_Skullcrusher/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/EZ-Bar_Skullcrusher/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/EZ-Bar_Skullcrusher/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Incline Barbell Triceps Extension','incline-barbell-triceps-extension','Ejercicio de empuje, aislamiento.',ARRAY['Hold a barbell with an overhand grip (palms down) that is a little closer together than shoulder width.','Lie back on an incline bench set at any angle between 45-75-degrees.','Bring the bar overhead with your arms extended and elbows in. The arms should be in line with the torso above the head. This will be your starting position.','Now lower the bar in a semicircular motion behind your head until your forearms touch your biceps. Inhale as you perform this movement. Tip: Keep your upper arms stationary and close to your head at all times. Only the forearms should move.','Return to the starting position as you breathe out and you contract the triceps. Hold the contraction for a second.','Repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY['biceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Barbell_Triceps_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Barbell_Triceps_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Barbell_Triceps_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Kneeling Cable Triceps Extension','kneeling-cable-triceps-extension','Ejercicio de empuje, aislamiento.',ARRAY['Place a bench sideways in front of a high pulley machine.','Hold a straight bar attachment above your head with your hands about 6 inches apart with your palms facing down.','Face away from the machine and kneel.','Place your head and the back of your upper arms on the bench. Your elbows should be bent with the forearms pointing towards the high pulley. This will be your starting position.','While keeping your upper arms close to your head at all times with the elbows in, press the bar out in a semicircular motion until the elbows are locked and your arms are parallel to the floor. Contract the triceps hard and keep this position for a second. Exhale as you perform this movement.','Slowly return to the starting position as you breathe in.','Repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_Cable_Triceps_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_Cable_Triceps_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_Cable_Triceps_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Low Cable Triceps Extension','low-cable-triceps-extension','Ejercicio de empuje, aislamiento.',ARRAY['Select the desired weight and lay down face up on the bench of a seated row machine that has a rope attached to it. Your head should be pointing towards the attachment.','Grab the outside of the rope ends with your palms facing each other (neutral grip).','Position your elbows so that they are bent at a 90 degree angle and your upper arms are perpendicular (90 degree angle) to your torso. Tip: Keep the elbows in and make sure that the upper arms point to the ceiling while your forearms point towards the pulley above your head. This will be your starting position.','As you breathe out, extend your lower arms until they are straight and vertical. The upper arms and elbows remain stationary throughout the movement. Only the forearms should move. Contract the triceps hard for a second.','As you breathe in slowly return to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Low_Cable_Triceps_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Low_Cable_Triceps_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Low_Cable_Triceps_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Lying Close-Grip Barbell Triceps Extension Behind The Head','lying-close-grip-barbell-triceps-extension-behind-the-head','Ejercicio de empuje, aislamiento.',ARRAY['While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head close to the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles.','Extend your arms in front of you and slowly bring the bar back in a semi circular motion (while keeping the arms extended) to a position over your head. At the end of this step your arms should be overhead and parallel to the floor. This will be your starting position. Tip: Keep your elbows in at all times.','As you inhale, lower the bar by bending at the elbows and while keeping the upper arm stationary. Keep lowering the bar until your forearms are perpendicular to the floor.','As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion until the lower arms are also parallel to the floor. Contract the triceps hard at the top of the movement for a second. Tip: Again, only the forearms should move. The upper arms should remain stationary at all times.','Repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Barbell Glute Bridge','barbell-glute-bridge','Ejercicio de empuje, compuesto.',ARRAY['Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.','Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.','Extend as far as possible, then reverse the motion to return to the starting position.']::text[],'gluteos',ARRAY['piernas']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Glute_Bridge/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Glute_Bridge/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Glute_Bridge/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Barbell Hip Thrust','barbell-hip-thrust','Ejercicio de empuje, compuesto.',ARRAY['Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.','Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.','Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position.']::text[],'gluteos',ARRAY['piernas']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Hip_Thrust/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Hip_Thrust/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Hip_Thrust/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Flutter Kicks','flutter-kicks','Ejercicio de tirón, compuesto.',ARRAY['On a flat bench lie facedown with the hips on the edge of the bench, the legs straight with toes high off the floor and with the arms on top of the bench holding on to the front edge.','Squeeze your glutes and hamstrings and straighten the legs until they are level with the hips. This will be your starting position.','Start the movement by lifting the left leg higher than the right leg.','Then lower the left leg as you lift the right leg.','Continue alternating in this manner (as though you are doing a flutter kick in water) until you have done the recommended amount of repetitions for each leg. Make sure that you keep a controlled movement at all times. Tip: You will breathe normally as you perform this movement.']::text[],'gluteos',ARRAY['piernas']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Flutter_Kicks/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Flutter_Kicks/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Flutter_Kicks/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Glute Kickback','glute-kickback','Ejercicio de empuje, compuesto.',ARRAY['Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.','As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.','Go back to the initial position as you inhale and now repeat with the left leg.','Continue to alternate legs until all of the recommended repetitions have been performed.']::text[],'gluteos',ARRAY['piernas']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Glute_Kickback/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Glute_Kickback/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Glute_Kickback/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Hip Extension with Bands','hip-extension-with-bands','Ejercicio de empuje, compuesto.',ARRAY['Secure one end of the band to the lower portion of a post and attach the other to one ankle.','Facing the attachment point of the band, hold on to the column to stabilize yourself.','Keeping your head and your chest up, move the resisted leg back as far as you can while keeping the knee straight.','Return the leg to the starting position.']::text[],'gluteos',ARRAY['piernas']::muscle_group_type[],ARRAY['bandas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hip_Extension_with_Bands/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hip_Extension_with_Bands/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hip_Extension_with_Bands/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Hip Lift with Band','hip-lift-with-band','Ejercicio de empuje, compuesto.',ARRAY['After choosing a suitable band, lay down in the middle of the rack, after securing the band on either side of you. If your rack doesn''t have pegs, the band can be secured using heavy dumbbells or similar objects, just ensure they won''t move.','Adjust your position so that the band is directly over your hips. Bend your knees and place your feet flat on the floor. Your hands can be on the floor or holding the band in position.','Keeping your shoulders on the ground, drive through your heels to raise your hips, pushing into the band as high as you can.','Pause at the top of the motion, and return to the starting position.']::text[],'gluteos',ARRAY['piernas']::muscle_group_type[],ARRAY['bandas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hip_Lift_with_Band/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hip_Lift_with_Band/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hip_Lift_with_Band/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Kneeling Squat','kneeling-squat','Ejercicio de empuje, compuesto.',ARRAY['Set the bar to the proper height in a power rack. Kneel behind the bar; it may be beneficial to put a mat down to pad your knees. Slide under the bar, racking it across the back of your shoulders. Your shoulder blades should be retracted and the bar tight across your back. Unrack the weight.','With your head looking forward, sit back with your butt until you touch your calves.','Reverse the motion, returning the torso to an upright position.']::text[],'gluteos',ARRAY['abdomen','piernas','espalda']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_Squat/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_Squat/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_Squat/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Pull Through','pull-through','Ejercicio de tirón, compuesto.',ARRAY['Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with your feet set wide apart.','Begin the movement by reaching through your legs as far as possible, bending at the hips. Keep your knees slightly bent. Keeping your arms straight, extend through the hip to stand straight up. Avoid pulling upward through the shoulders; all of the motion should originate through the hips.']::text[],'gluteos',ARRAY['piernas','espalda']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Pull_Through/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Pull_Through/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Pull_Through/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Step-up with Knee Raise','step-up-with-knee-raise','Ejercicio de empuje, compuesto.',ARRAY['Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.','Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.','Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg.']::text[],'gluteos',ARRAY['piernas']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Step-up_with_Knee_Raise/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Step-up_with_Knee_Raise/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Step-up_with_Knee_Raise/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Butt Lift (Bridge)','butt-lift-bridge','Ejercicio de empuje, aislamiento.',ARRAY['Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.','Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.','Slowly go back to the starting position as you breathe in.']::text[],'gluteos',ARRAY['piernas']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Butt_Lift_Bridge/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Butt_Lift_Bridge/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Butt_Lift_Bridge/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Kneeling Jump Squat','kneeling-jump-squat','Ejercicio de empuje, compuesto.',ARRAY['Begin kneeling on the floor with a barbell racked across the back of your shoulders, or you can use your body weight for this exercise. This can be done inside of a power rack to make unracking easier.','Sit back with your hips until your glutes touch your feet, keeping your head and chest up.','Explode up with your hips, generating enough power to land with your feet flat on the floor.','Continue with the squat by driving through your heels and extending the knees to come to a standing position.']::text[],'gluteos',ARRAY['piernas']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_Jump_Squat/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_Jump_Squat/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_Jump_Squat/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],5,'3-5',180,ARRAY[]::text[]),
('Leg Lift','leg-lift','Ejercicio de empuje, aislamiento.',ARRAY['While standing up straight with both feet next to each other at around shoulder width, grab a sturdy surface such as the sides of a squat rack or the top of a chair to brace yourself and keep balance.','With or without an ankle weight, lift one leg behind you as if performing a leg curl but standing up while keeping the other leg straight. Breathe out as you perform this movement.','Slowly bring the raised leg back to the floor as you breathe in.','Repeat for the recommended amount of repetitions.','Repeat the movement with the opposite leg.']::text[],'gluteos',ARRAY['piernas']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leg_Lift/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leg_Lift/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leg_Lift/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('One-Legged Cable Kickback','one-legged-cable-kickback','Ejercicio de empuje, aislamiento.',ARRAY['Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle.','Face the weight stack from a distance of about two feet, grasping the steel frame for support.','While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly "kick" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out. Tip: At full extension, squeeze your glutes for a second in order to achieve a peak contraction.','Now slowly bring your working leg forward, resisting the pull of the cable until you reach the starting position.','Repeat for the recommended amount of repetitions.','Switch legs and repeat the movement for the other side.']::text[],'gluteos',ARRAY['piernas']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Legged_Cable_Kickback/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Legged_Cable_Kickback/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One-Legged_Cable_Kickback/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Single Leg Glute Bridge','single-leg-glute-bridge','Ejercicio de empuje, aislamiento.',ARRAY['Lay on the floor with your feet flat and knees bent.','Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.','Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.','Extend as far as possible, pause and then return to the starting position.']::text[],'gluteos',ARRAY['piernas']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Single_Leg_Glute_Bridge/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Single_Leg_Glute_Bridge/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Single_Leg_Glute_Bridge/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[])
